"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"about-section":{"path":"sections/about-section.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Materials and care editorial","presets":[{"blocks":[],"name":"Materials and care editorial","settings":{}}],"settings":[{"default":"Know the material","id":"eyebrow","label":"Eyebrow","type":"text"},{"default":"The details make the difference.","id":"title","label":"Heading","type":"text"},{"id":"content","label":"Merchant-supplied material story","type":"textarea"},{"id":"image","label":"Material photograph","type":"image"},{"default":"","id":"imageAlt","label":"Photograph description","type":"text"},{"default":"","id":"linkLabel","label":"Link label","type":"text"},{"default":"","id":"linkUrl","label":"Link destination","type":"url"}],"tag":"section"},"source":"<section class=\"hab-theme\" data-section-id=\"{{ section.id }}\">{% if section.settings.content != blank or section.settings.image != blank %}<div class=\"hab-wrap hab-section hab-material{% if section.settings.image == blank %} hab-material-empty{% endif %}\">{% if section.settings.image != blank %}<img src=\"{{ section.settings.image | image_url }}\" alt=\"{{ section.settings.imageAlt }}\" loading=\"lazy\" decoding=\"async\">{% endif %}<div><span class=\"hab-eyebrow\">{{ section.settings.eyebrow }}</span><h2>{{ section.settings.title }}</h2><p>{{ section.settings.content }}</p>{% if section.settings.linkLabel != blank and section.settings.linkUrl != blank %}<a class=\"hab-link\" href=\"{{ section.settings.linkUrl | store_url }}\">{{ section.settings.linkLabel }}</a>{% endif %}</div></div>{% endif %}</section>\n{% schema %}\n{\"name\":\"Materials and care editorial\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Eyebrow\",\"default\":\"Know the material\",\"id\":\"eyebrow\"},{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"The details make the difference.\",\"id\":\"title\"},{\"type\":\"textarea\",\"label\":\"Merchant-supplied material story\",\"id\":\"content\"},{\"type\":\"image\",\"label\":\"Material photograph\",\"id\":\"image\"},{\"type\":\"text\",\"label\":\"Photograph description\",\"default\":\"\",\"id\":\"imageAlt\"},{\"type\":\"text\",\"label\":\"Link label\",\"default\":\"\",\"id\":\"linkLabel\"},{\"type\":\"url\",\"label\":\"Link destination\",\"default\":\"\",\"id\":\"linkUrl\"}],\"blocks\":[],\"presets\":[{\"name\":\"Materials and care editorial\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"announcement-bar":{"path":"sections/announcement-bar.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Announcement Bar","presets":[{"blocks":[],"name":"Announcement Bar","settings":{}}],"settings":[{"default":"Discover our latest products.","id":"text","label":"Message","type":"text"},{"default":"Shop now","id":"linkLabel","label":"Link label","type":"text"},{"default":"/products","id":"linkHref","label":"Link URL","type":"url"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-announcement-bar\" data-section-id=\"{{ section.id }}\">\n  <div class=\"lb-announcement-bar__inner\">\n    <span>{{ section.settings.text }}</span>\n    {% if section.settings.linkLabel %}<a href=\"{{ section.settings.linkHref | store_url }}\">{{ section.settings.linkLabel }}</a>{% endif %}\n  </div>\n</section>\n</div>\n{% schema %}\n{\"name\":\"Announcement Bar\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Message\",\"default\":\"Discover our latest products.\",\"id\":\"text\"},{\"type\":\"text\",\"label\":\"Link label\",\"default\":\"Shop now\",\"id\":\"linkLabel\"},{\"type\":\"url\",\"label\":\"Link URL\",\"default\":\"/products\",\"id\":\"linkHref\"}],\"blocks\":[],\"presets\":[{\"name\":\"Announcement Bar\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"app-block-slot":{"path":"sections/app-block-slot.liquid","schema":{"blocks":[{"name":"App block","settings":[],"type":"@app"}],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"App Block Slot","presets":[{"blocks":[],"name":"App Block Slot","settings":{}}],"settings":[{"id":"title","label":"Title","type":"text"},{"default":"storefront.home.after-hero","id":"slot","label":"Slot","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-app-block-slot\" data-section-id=\"{{ section.id }}\">\n  {% if section.settings.title %}<h2>{{ section.settings.title }}</h2>{% endif %}\n  {% for block in section.blocks %}{{ block.content | raw }}{% endfor %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"App Block Slot\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Title\",\"id\":\"title\"},{\"type\":\"text\",\"label\":\"Slot\",\"default\":\"storefront.home.after-hero\",\"id\":\"slot\"}],\"blocks\":[{\"type\":\"@app\",\"name\":\"App block\",\"settings\":[]}],\"presets\":[{\"name\":\"App Block Slot\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"article-content":{"path":"sections/article-content.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Article Content","presets":[{"blocks":[],"name":"Article Content","settings":{}}],"settings":[],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-article\" data-section-id=\"{{ section.id }}\">\n  {% if article %}\n  <h1 class=\"lb-article__title\">{{ article.title }}</h1>\n  {% if article.published_at %}<time class=\"lb-article__date\" datetime=\"{{ article.published_at }}\">{{ article.published_at | date: \"%B %-d, %Y\" }}</time>{% endif %}\n  {% if article.image %}<img class=\"lb-article__image\" src=\"{{ article.image | image_url }}\" alt=\"{{ article.title }}\">{% endif %}\n  {% if article.body_html != blank %}<div class=\"lb-article__body\">{{ article.body_html | raw }}</div>{% endif %}\n  {% else %}\n  <p class=\"lb-article__missing\">Article not found.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Article Content\",\"tag\":\"section\",\"settings\":[],\"blocks\":[],\"presets\":[{\"name\":\"Article Content\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"banner-carousel":{"path":"sections/banner-carousel.liquid","schema":{"blocks":[{"name":"Slide","settings":[{"id":"heading","label":"Heading","type":"text"},{"id":"image","label":"Image","type":"image"},{"id":"link","label":"Link","type":"url"}],"type":"slide"}],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Banner Carousel","presets":[{"blocks":[],"name":"Banner Carousel","settings":{}}],"settings":[{"id":"title","label":"Title","type":"text"},{"default":true,"id":"autoplay","label":"Autoplay","type":"toggle"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-banner-carousel\" data-section-id=\"{{ section.id }}\" data-autoplay=\"{{ section.settings.autoplay }}\">\n  {% if section.settings.title %}<h2>{{ section.settings.title }}</h2>{% endif %}\n  <div class=\"lb-banner-carousel__slides\">\n    {% for block in section.blocks %}<a {{ block.editor_attributes | raw }} href=\"{{ block.settings.link | store_url }}\">{% if block.settings.image %}<img src=\"{{ block.settings.image | image_url }}\" alt=\"{{ block.settings.heading }}\">{% endif %}<h3>{{ block.settings.heading }}</h3>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</a>{% endfor %}\n  </div>\n</section>\n</div>\n{% schema %}\n{\"name\":\"Banner Carousel\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Title\",\"id\":\"title\"},{\"type\":\"toggle\",\"label\":\"Autoplay\",\"default\":true,\"id\":\"autoplay\"}],\"blocks\":[{\"type\":\"slide\",\"name\":\"Slide\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"id\":\"heading\"},{\"type\":\"image\",\"label\":\"Image\",\"id\":\"image\"},{\"type\":\"url\",\"label\":\"Link\",\"id\":\"link\"}]}],\"presets\":[{\"name\":\"Banner Carousel\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"blog-listing":{"path":"sections/blog-listing.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Blog Listing","presets":[{"blocks":[],"name":"Blog Listing","settings":{}}],"settings":[{"default":"Our Blog","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-blog-listing\" data-section-id=\"{{ section.id }}\">\n  <h1 class=\"lb-blog-listing__heading\">{{ section.settings.heading }}</h1>\n  {% if blog.articles and blog.articles.size > 0 %}\n  <div class=\"lb-blog-listing__articles\">\n    {% for article in blog.articles %}\n    <article class=\"lb-blog-article-card\">\n      <h2 class=\"lb-blog-article-card__title\"><a href=\"{{ routes.blog_url }}/{{ article.slug }}\">{{ article.title }}</a></h2>\n      {% if article.excerpt %}<p class=\"lb-blog-article-card__excerpt\">{{ article.excerpt }}</p>{% endif %}\n      {% if article.published_at %}<time class=\"lb-blog-article-card__date\" datetime=\"{{ article.published_at }}\">{{ article.published_at | date: \"%B %-d, %Y\" }}</time>{% endif %}\n    </article>\n    {% endfor %}\n  </div>\n  {% if blog.pages_count and blog.pages_count > 1 %}\n  <nav class=\"lb-blog-listing__pagination\" aria-label=\"Blog pagination\">\n    {% if blog.current_page and blog.current_page > 1 %}<a class=\"lb-blog-listing__prev\" href=\"{{ routes.blog_url }}?page={{ blog.current_page | minus: 1 }}\" rel=\"prev\">Previous</a>{% endif %}\n    {% assign next_page = blog.current_page | plus: 1 %}\n    {% if next_page <= blog.pages_count %}<a class=\"lb-blog-listing__next\" href=\"{{ routes.blog_url }}?page={{ next_page }}\" rel=\"next\">Next</a>{% endif %}\n  </nav>\n  {% endif %}\n  {% else %}\n  <p class=\"lb-blog-listing__empty\">No posts published yet.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Blog Listing\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Our Blog\",\"id\":\"heading\"}],\"blocks\":[],\"presets\":[{\"name\":\"Blog Listing\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"brand-marquee":{"path":"sections/brand-marquee.liquid","schema":{"blocks":[{"name":"Brand","settings":[{"id":"name","label":"Name","type":"text"}],"type":"brand"}],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Brand Marquee","presets":[{"blocks":[],"name":"Brand Marquee","settings":{}}],"settings":[{"default":"Featured brands","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-brand-marquee\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  <div>{% for block in section.blocks %}<span {{ block.editor_attributes | raw }}>{{ block.settings.name }}{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</span>{% endfor %}</div>\n</section>\n</div>\n{% schema %}\n{\"name\":\"Brand Marquee\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Title\",\"default\":\"Featured brands\",\"id\":\"title\"}],\"blocks\":[{\"type\":\"brand\",\"name\":\"Brand\",\"settings\":[{\"type\":\"text\",\"label\":\"Name\",\"id\":\"name\"}]}],\"presets\":[{\"name\":\"Brand Marquee\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"cart-summary":{"path":"sections/cart-summary.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Cart","presets":[{"blocks":[],"name":"Cart","settings":{}}],"settings":[{"default":"Your cart","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-cart-page\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}</h1>\n  <lb-cart data-lb-island=\"cart\" data-base-path=\"/store/{{ shop.subdomain }}\">\n    {% if cart.item_count > 0 %}\n    <ul class=\"lb-cart__items\">{% for item in cart.items %}<li class=\"lb-cart__item\"><span class=\"lb-cart__title\">{{ item.title }}</span><span class=\"lb-cart__qty\">x{{ item.quantity }}</span><span class=\"lb-cart__line\">{{ item.line_price | money_with_currency: cart.currency }}</span></li>{% endfor %}</ul>\n    <div class=\"lb-liquid-cart__totals\">\n      {% if cart.subtotal %}<div class=\"lb-liquid-cart__row\"><span>Subtotal</span><span>{{ cart.subtotal | money_with_currency: cart.currency }}</span></div>{% endif %}\n      {% if cart.coupon_codes.size > 0 %}<div class=\"lb-liquid-cart__row\"><span>Coupons</span><span>{{ cart.coupon_codes | join: \", \" }}</span></div>{% endif %}\n      {% if cart.discount_total %}<div class=\"lb-liquid-cart__row\"><span>Discounts</span><span>{{ cart.discount_total | money_with_currency: cart.currency }}</span></div>{% endif %}\n      {% if cart.shipping_total %}<div class=\"lb-liquid-cart__row\"><span>Shipping</span><span>{{ cart.shipping_total | money_with_currency: cart.currency }}</span></div>{% endif %}\n      {% if cart.tax_total %}<div class=\"lb-liquid-cart__row\"><span>Tax (GST)</span><span>{{ cart.tax_total | money_with_currency: cart.currency }}</span></div>{% endif %}\n    </div>\n    <p class=\"lb-cart__total\">Total: {{ cart.total_price | money_with_currency: cart.currency }}</p>\n    <a class=\"lb-cart__checkout\" href=\"{{ cart.checkout_url }}\">Checkout</a>\n    {% else %}<p class=\"lb-cart__empty\">Your cart is empty. <a href=\"{{ routes.all_products_collection_url }}\">Browse products</a></p>{% endif %}\n  </lb-cart>\n</section>\n</div>\n{% schema %}\n{\"name\":\"Cart\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Your cart\",\"id\":\"heading\"}],\"blocks\":[],\"presets\":[{\"name\":\"Cart\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"category-grid":{"path":"sections/category-grid.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Category Grid","presets":[{"blocks":[],"name":"Category Grid","settings":{}}],"settings":[{"default":"Shop by style","id":"title","label":"Heading","type":"text"},{"id":"subtitle","label":"Subheading","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-category-grid\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  <p>{{ section.settings.subtitle }}</p>\n  {% if collections.size > 0 %}\n  <div class=\"lb-category-grid__items\">{% for item in collections %}<a class=\"lb-category-card\" href=\"{{ routes.collections_url }}/{{ item.handle }}\"><strong>{{ item.title }}</strong>{% if item.description %}<span>{{ item.description | strip_html | truncate: 60 }}</span>{% endif %}</a>{% endfor %}</div>\n  {% else %}\n  <div class=\"lb-category-grid__empty\"><h2>No collections yet</h2><p>Collections added to this store will appear here.</p></div>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Category Grid\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Shop by style\",\"id\":\"title\"},{\"type\":\"text\",\"label\":\"Subheading\",\"id\":\"subtitle\"}],\"blocks\":[],\"presets\":[{\"name\":\"Category Grid\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"collection-banner":{"path":"sections/collection-banner.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Collection Banner","presets":[{"blocks":[],"name":"Collection Banner","settings":{}}],"settings":[{"default":true,"id":"showDescription","label":"Show description","type":"toggle"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-collection-banner\" data-section-id=\"{{ section.id }}\">\n  {% if collection.image_url != blank %}<img class=\"lb-collection-banner__image\" src=\"{{ collection.image_url | image_url }}\" alt=\"{{ collection.title }}\">{% endif %}\n  <h1>{{ collection.title }}</h1>\n  {% if collection.products.size > 0 %}<p class=\"lb-collection-banner__count\">{{ collection.products.size }} products</p>{% endif %}\n  {% if section.settings.showDescription and collection.description %}<div class=\"lb-collection-banner__desc\">{{ collection.description }}</div>{% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Collection Banner\",\"tag\":\"section\",\"settings\":[{\"type\":\"toggle\",\"label\":\"Show description\",\"default\":true,\"id\":\"showDescription\"}],\"blocks\":[],\"presets\":[{\"name\":\"Collection Banner\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"collection-filter":{"path":"sections/collection-filter.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Room and furniture discovery","presets":[{"blocks":[],"name":"Room and furniture discovery","settings":{}}],"settings":[{"default":"A space to slow down","id":"eyebrow","label":"Eyebrow","type":"text"},{"default":"Furniture","id":"title","label":"Fallback heading","type":"text"},{"default":true,"id":"showDimensionFilters","label":"Show supported dimension and material filters","type":"toggle"}],"tag":"section"},"source":"<section class=\"hab-theme\" data-section-id=\"{{ section.id }}\"><div class=\"hab-wrap hab-section hab-discovery\"><nav class=\"hab-breadcrumb\" aria-label=\"Breadcrumb\"><a href=\"{{ routes.root_url }}\">Home</a><span aria-hidden=\"true\">/</span><span>{{ collection.title | default: 'Furniture' }}</span></nav><span class=\"hab-eyebrow\">{{ section.settings.eyebrow }}</span><h1>{{ collection.title | default: section.settings.title }}</h1>{% if collection.description != blank %}<p>{{ collection.description }}</p>{% endif %}<nav class=\"hab-category-rail\" aria-label=\"Furniture collections\">{% for room in collections limit: 8 %}<a class=\"hab-link\" href=\"{{ routes.collections_url }}/{{ room.handle }}\">{{ room.title }}</a>{% endfor %}</nav>\n{% assign habitat_search = request.query.search %}{% assign habitat_sort = request.query.sort | default: 'display_order' %}\n{% assign habitat_material = request.query.material %}{% assign habitat_show_material = false %}{% assign habitat_finish = request.query.finish %}{% assign habitat_show_finish = false %}{% assign habitat_max_width_cm = request.query.max_width_cm %}{% assign habitat_show_max_width_cm = false %}{% assign habitat_max_depth_cm = request.query.max_depth_cm %}{% assign habitat_show_max_depth_cm = false %}\n{% for field in collection.discovery_query_fields %}{% case field.key %}{% when 'search' %}{% assign habitat_search = field.value %}{% when 'sort' %}{% assign habitat_sort = field.value %}{% when 'material' %}{% assign habitat_material = field.value %}{% when 'finish' %}{% assign habitat_finish = field.value %}{% when 'max_width_cm' %}{% assign habitat_max_width_cm = field.value %}{% when 'max_depth_cm' %}{% assign habitat_max_depth_cm = field.value %}{% endcase %}{% endfor %}\n{% if section.settings.showDimensionFilters %}{% if collection.furniture_filters_available %}{% for facet in collection.furniture_facets %}{% if facet.count > 0 %}{% case facet.key %}{% when 'material' %}{% assign habitat_show_material = true %}{% when 'finish' %}{% assign habitat_show_finish = true %}{% endcase %}{% endif %}{% endfor %}{% endif %}{% if collection.measurement_capabilities.max_width_cm.available == true %}{% assign habitat_show_max_width_cm = true %}{% endif %}{% if collection.measurement_capabilities.max_depth_cm.available == true %}{% assign habitat_show_max_depth_cm = true %}{% endif %}{% endif %}\n<form class=\"hab-filters\" method=\"get\" action=\"{{ request.path }}\">\n<label>Search furniture<input type=\"search\" name=\"search\" value=\"{{ habitat_search }}\" maxlength=\"200\" placeholder=\"Name or material\"></label>\n{% if habitat_show_max_width_cm %}<label>Maximum assembled width (cm)<input type=\"number\" name=\"max_width_cm\" value=\"{{ habitat_max_width_cm }}\" max=\"1000000\" step=\"any\"></label>{% endif %}{% if habitat_show_max_depth_cm %}<label>Maximum assembled depth (cm)<input type=\"number\" name=\"max_depth_cm\" value=\"{{ habitat_max_depth_cm }}\" max=\"1000000\" step=\"any\"></label>{% endif %}{% if habitat_show_material %}<label>Material<select name=\"material\"><option value=\"\">Any material</option>{% assign habitat_supplied_material = false %}{% if habitat_material != blank %}{% for facet in collection.furniture_facets %}{% if facet.key == 'material' and facet.count > 0 and facet.value == habitat_material and habitat_supplied_material == false %}<option value=\"{{ facet.value }}\" selected>{{ facet.label }}</option>{% assign habitat_supplied_material = true %}{% endif %}{% endfor %}{% unless habitat_supplied_material %}<option value=\"{{ habitat_material }}\" selected>Current: {{ habitat_material }}</option>{% endunless %}{% endif %}{% for facet in collection.furniture_facets %}{% if facet.key == 'material' and facet.count > 0 and facet.value != habitat_material %}<option value=\"{{ facet.value }}\">{{ facet.label }}</option>{% endif %}{% endfor %}</select></label>{% endif %}{% if habitat_show_finish %}<label>Finish<select name=\"finish\"><option value=\"\">Any finish</option>{% assign habitat_supplied_finish = false %}{% if habitat_finish != blank %}{% for facet in collection.furniture_facets %}{% if facet.key == 'finish' and facet.count > 0 and facet.value == habitat_finish and habitat_supplied_finish == false %}<option value=\"{{ facet.value }}\" selected>{{ facet.label }}</option>{% assign habitat_supplied_finish = true %}{% endif %}{% endfor %}{% unless habitat_supplied_finish %}<option value=\"{{ habitat_finish }}\" selected>Current: {{ habitat_finish }}</option>{% endunless %}{% endif %}{% for facet in collection.furniture_facets %}{% if facet.key == 'finish' and facet.count > 0 and facet.value != habitat_finish %}<option value=\"{{ facet.value }}\">{{ facet.label }}</option>{% endif %}{% endfor %}</select></label>{% endif %}\n<label>Sort<select name=\"sort\"><option value=\"display_order\"{% if habitat_sort == 'display_order' %} selected{% endif %}>Featured</option><option value=\"price-asc\"{% if habitat_sort == 'price-asc' %} selected{% endif %}>Price: low to high</option><option value=\"price-desc\"{% if habitat_sort == 'price-desc' %} selected{% endif %}>Price: high to low</option><option value=\"newest\"{% if habitat_sort == 'newest' %} selected{% endif %}>Newest</option><option value=\"name\"{% if habitat_sort == 'name' %} selected{% endif %}>Name</option></select></label>\n{% for field in collection.discovery_query_fields %}{% assign habitat_keep_field = true %}{% if field.key == 'page' or field.key == 'search' or field.key == 'sort' %}{% assign habitat_keep_field = false %}{% endif %}{% if field.key == 'material' and habitat_show_material %}{% assign habitat_keep_field = false %}{% endif %}{% if field.key == 'finish' and habitat_show_finish %}{% assign habitat_keep_field = false %}{% endif %}{% if field.key == 'max_width_cm' and habitat_show_max_width_cm %}{% assign habitat_keep_field = false %}{% endif %}{% if field.key == 'max_depth_cm' and habitat_show_max_depth_cm %}{% assign habitat_keep_field = false %}{% endif %}{% if habitat_keep_field %}<input type=\"hidden\" name=\"{{ field.key }}\" value=\"{{ field.value }}\">{% endif %}{% endfor %}\n<button class=\"hab-button\" type=\"submit\">Apply</button>{% if collection.clear_filters_url != blank %}<a class=\"hab-link\" href=\"{{ collection.clear_filters_url }}\">Clear filters</a>{% endif %}</form>\n{% if collection.active_filters.size > 0 %}<nav class=\"hab-active-filters\" aria-label=\"Applied filters\">{% for filter in collection.active_filters %}<a class=\"hab-link\" href=\"{{ filter.clear_url }}\" aria-label=\"Remove {{ filter.label }}\">{{ filter.label }} <span aria-hidden=\"true\">×</span></a>{% endfor %}</nav>{% endif %}\n{% if collection.total != nil %}<p class=\"hab-count\">{{ collection.total }} pieces</p>{% endif %}<p class=\"hab-support\">Assembled measurements describe room fit. Check separate package measurements for access.</p></div></section>\n{% schema %}\n{\"name\":\"Room and furniture discovery\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Eyebrow\",\"default\":\"A space to slow down\",\"id\":\"eyebrow\"},{\"type\":\"text\",\"label\":\"Fallback heading\",\"default\":\"Furniture\",\"id\":\"title\"},{\"type\":\"toggle\",\"label\":\"Show supported dimension and material filters\",\"default\":true,\"id\":\"showDimensionFilters\"}],\"blocks\":[],\"presets\":[{\"name\":\"Room and furniture discovery\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"collection-product-list":{"path":"sections/collection-product-list.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Furniture search results","presets":[{"blocks":[],"name":"Furniture search results","settings":{}}],"settings":[{"default":"Furniture","id":"title","label":"Fallback heading","type":"text"},{"default":true,"id":"showDimensionFilters","label":"Show supported dimension and material filters","type":"toggle"}],"tag":"section"},"source":"<section class=\"hab-theme\" data-section-id=\"{{ section.id }}\"><div class=\"hab-wrap hab-section\"><h1>{{ collection.title | default: section.settings.title }}</h1>\n{% assign habitat_search = request.query.search %}{% assign habitat_sort = request.query.sort | default: 'display_order' %}\n{% assign habitat_material = request.query.material %}{% assign habitat_show_material = false %}{% assign habitat_finish = request.query.finish %}{% assign habitat_show_finish = false %}{% assign habitat_max_width_cm = request.query.max_width_cm %}{% assign habitat_show_max_width_cm = false %}{% assign habitat_max_depth_cm = request.query.max_depth_cm %}{% assign habitat_show_max_depth_cm = false %}\n{% for field in collection.discovery_query_fields %}{% case field.key %}{% when 'search' %}{% assign habitat_search = field.value %}{% when 'sort' %}{% assign habitat_sort = field.value %}{% when 'material' %}{% assign habitat_material = field.value %}{% when 'finish' %}{% assign habitat_finish = field.value %}{% when 'max_width_cm' %}{% assign habitat_max_width_cm = field.value %}{% when 'max_depth_cm' %}{% assign habitat_max_depth_cm = field.value %}{% endcase %}{% endfor %}\n{% if section.settings.showDimensionFilters %}{% if collection.furniture_filters_available %}{% for facet in collection.furniture_facets %}{% if facet.count > 0 %}{% case facet.key %}{% when 'material' %}{% assign habitat_show_material = true %}{% when 'finish' %}{% assign habitat_show_finish = true %}{% endcase %}{% endif %}{% endfor %}{% endif %}{% if collection.measurement_capabilities.max_width_cm.available == true %}{% assign habitat_show_max_width_cm = true %}{% endif %}{% if collection.measurement_capabilities.max_depth_cm.available == true %}{% assign habitat_show_max_depth_cm = true %}{% endif %}{% endif %}\n<form class=\"hab-filters\" method=\"get\" action=\"{{ request.path }}\">\n<label>Search furniture<input type=\"search\" name=\"search\" value=\"{{ habitat_search }}\" maxlength=\"200\" placeholder=\"Name or material\"></label>\n{% if habitat_show_max_width_cm %}<label>Maximum assembled width (cm)<input type=\"number\" name=\"max_width_cm\" value=\"{{ habitat_max_width_cm }}\" max=\"1000000\" step=\"any\"></label>{% endif %}{% if habitat_show_max_depth_cm %}<label>Maximum assembled depth (cm)<input type=\"number\" name=\"max_depth_cm\" value=\"{{ habitat_max_depth_cm }}\" max=\"1000000\" step=\"any\"></label>{% endif %}{% if habitat_show_material %}<label>Material<select name=\"material\"><option value=\"\">Any material</option>{% assign habitat_supplied_material = false %}{% if habitat_material != blank %}{% for facet in collection.furniture_facets %}{% if facet.key == 'material' and facet.count > 0 and facet.value == habitat_material and habitat_supplied_material == false %}<option value=\"{{ facet.value }}\" selected>{{ facet.label }}</option>{% assign habitat_supplied_material = true %}{% endif %}{% endfor %}{% unless habitat_supplied_material %}<option value=\"{{ habitat_material }}\" selected>Current: {{ habitat_material }}</option>{% endunless %}{% endif %}{% for facet in collection.furniture_facets %}{% if facet.key == 'material' and facet.count > 0 and facet.value != habitat_material %}<option value=\"{{ facet.value }}\">{{ facet.label }}</option>{% endif %}{% endfor %}</select></label>{% endif %}{% if habitat_show_finish %}<label>Finish<select name=\"finish\"><option value=\"\">Any finish</option>{% assign habitat_supplied_finish = false %}{% if habitat_finish != blank %}{% for facet in collection.furniture_facets %}{% if facet.key == 'finish' and facet.count > 0 and facet.value == habitat_finish and habitat_supplied_finish == false %}<option value=\"{{ facet.value }}\" selected>{{ facet.label }}</option>{% assign habitat_supplied_finish = true %}{% endif %}{% endfor %}{% unless habitat_supplied_finish %}<option value=\"{{ habitat_finish }}\" selected>Current: {{ habitat_finish }}</option>{% endunless %}{% endif %}{% for facet in collection.furniture_facets %}{% if facet.key == 'finish' and facet.count > 0 and facet.value != habitat_finish %}<option value=\"{{ facet.value }}\">{{ facet.label }}</option>{% endif %}{% endfor %}</select></label>{% endif %}\n<label>Sort<select name=\"sort\"><option value=\"display_order\"{% if habitat_sort == 'display_order' %} selected{% endif %}>Featured</option><option value=\"price-asc\"{% if habitat_sort == 'price-asc' %} selected{% endif %}>Price: low to high</option><option value=\"price-desc\"{% if habitat_sort == 'price-desc' %} selected{% endif %}>Price: high to low</option><option value=\"newest\"{% if habitat_sort == 'newest' %} selected{% endif %}>Newest</option><option value=\"name\"{% if habitat_sort == 'name' %} selected{% endif %}>Name</option></select></label>\n{% for field in collection.discovery_query_fields %}{% assign habitat_keep_field = true %}{% if field.key == 'page' or field.key == 'search' or field.key == 'sort' %}{% assign habitat_keep_field = false %}{% endif %}{% if field.key == 'material' and habitat_show_material %}{% assign habitat_keep_field = false %}{% endif %}{% if field.key == 'finish' and habitat_show_finish %}{% assign habitat_keep_field = false %}{% endif %}{% if field.key == 'max_width_cm' and habitat_show_max_width_cm %}{% assign habitat_keep_field = false %}{% endif %}{% if field.key == 'max_depth_cm' and habitat_show_max_depth_cm %}{% assign habitat_keep_field = false %}{% endif %}{% if habitat_keep_field %}<input type=\"hidden\" name=\"{{ field.key }}\" value=\"{{ field.value }}\">{% endif %}{% endfor %}\n<button class=\"hab-button\" type=\"submit\">Apply</button>{% if collection.clear_filters_url != blank %}<a class=\"hab-link\" href=\"{{ collection.clear_filters_url }}\">Clear filters</a>{% endif %}</form>\n{% if collection.active_filters.size > 0 %}<nav class=\"hab-active-filters\" aria-label=\"Applied filters\">{% for filter in collection.active_filters %}<a class=\"hab-link\" href=\"{{ filter.clear_url }}\" aria-label=\"Remove {{ filter.label }}\">{{ filter.label }} <span aria-hidden=\"true\">×</span></a>{% endfor %}</nav>{% endif %}\n{% if collection.total != nil %}<p class=\"hab-count\">{{ collection.total }} pieces</p>{% endif %}{% if collection.products.size > 0 %}<div class=\"hab-grid\">{% for item in collection.products %}<article class=\"hab-card\"><a class=\"hab-card-image\" href=\"{{ item.url }}\">{% if item.featured_image != blank %}<img src=\"{{ item.featured_image | image_url }}\" alt=\"{{ item.title }}\" loading=\"lazy\" decoding=\"async\">{% else %}<span class=\"hab-placeholder\">Product photograph not supplied</span>{% endif %}{% if item.available == false %}<span class=\"hab-unavailable\">Unavailable</span>{% endif %}</a><div class=\"hab-card-heading\"><h3><a href=\"{{ item.url }}\">{{ item.title }}</a></h3><span class=\"hab-price\">{{ item.price | times: 100 | money_with_currency: item.currency }}</span></div>{% if item.furniture_display.assembled != blank %}<p class=\"hab-card-facts\">{{ item.furniture_display.assembled }}</p>{% elsif item.furniture.assembled != blank %}<p class=\"hab-card-facts\">{% if item.furniture.assembled.diameter %}{{ item.furniture.assembled.diameter }} Ø{% else %}{{ item.furniture.assembled.width | default: '—' }} W × {{ item.furniture.assembled.depth | default: '—' }} D{% endif %}{% if item.furniture.assembled.height %} × {{ item.furniture.assembled.height }} H{% endif %} {{ item.furniture.assembled.unit }}</p>{% else %}<p class=\"hab-card-facts\">Dimensions not supplied</p>{% endif %}{% if item.furniture.finish != blank %}<p class=\"hab-card-facts\">{{ item.furniture.finish }}</p>{% else %}{% for option in item.option_summaries %}<p class=\"hab-card-facts\">{{ option.name }}: {{ option.summary }}</p>{% endfor %}{% endif %}<a class=\"hab-link\" href=\"{{ item.url }}\">View dimensions &amp; options <span aria-hidden=\"true\">→</span></a></article>{% endfor %}</div><nav class=\"hab-pagination\" aria-label=\"Product pages\">{% if collection.pagination.previous_url != blank %}<a class=\"hab-link\" href=\"{{ collection.pagination.previous_url }}\">← Previous</a>{% endif %}{% if collection.pagination.page %}<span>Page {{ collection.pagination.page }}</span>{% endif %}{% if collection.pagination.next_url != blank %}<a class=\"hab-link\" href=\"{{ collection.pagination.next_url }}\">Next →</a>{% endif %}</nav>{% else %}<p>No pieces found.</p><a class=\"hab-link\" href=\"{{ routes.all_products_collection_url }}\">Explore all furniture</a>{% endif %}</div></section>\n{% schema %}\n{\"name\":\"Furniture search results\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Fallback heading\",\"default\":\"Furniture\",\"id\":\"title\"},{\"type\":\"toggle\",\"label\":\"Show supported dimension and material filters\",\"default\":true,\"id\":\"showDimensionFilters\"}],\"blocks\":[],\"presets\":[{\"name\":\"Furniture search results\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"contact-form":{"path":"sections/contact-form.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Contact Form","presets":[{"blocks":[],"name":"Contact Form","settings":{}}],"settings":[{"default":"Contact us","id":"title","label":"Title","type":"text"},{"id":"subtitle","label":"Subtitle","type":"text"},{"default":true,"id":"showPhone","label":"Show phone field","type":"toggle"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-contact-form\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  <p>{{ section.settings.subtitle }}</p>\n  <form action=\"/contact\" method=\"post\"><input name=\"name\" aria-label=\"Name\"><input type=\"email\" name=\"email\" aria-label=\"Email\">{% if section.settings.showPhone %}<input name=\"phone\" aria-label=\"Phone\">{% endif %}<button type=\"submit\">Send</button></form>\n</section>\n</div>\n{% schema %}\n{\"name\":\"Contact Form\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Title\",\"default\":\"Contact us\",\"id\":\"title\"},{\"type\":\"text\",\"label\":\"Subtitle\",\"id\":\"subtitle\"},{\"type\":\"toggle\",\"label\":\"Show phone field\",\"default\":true,\"id\":\"showPhone\"}],\"blocks\":[],\"presets\":[{\"name\":\"Contact Form\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"cta-section":{"path":"sections/cta-section.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Call to Action","presets":[{"blocks":[],"name":"Call to Action","settings":{}}],"settings":[{"default":"Ready to get started?","id":"heading","label":"Heading","type":"text"},{"id":"subheading","label":"Subheading","type":"text"},{"default":"Shop now","id":"ctaText","label":"Button text","type":"text"},{"default":"/products","id":"ctaLink","label":"Button link","type":"url"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-cta-section\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.heading }}</h2>\n  <p>{{ section.settings.subheading }}</p>\n  <a href=\"{{ section.settings.ctaLink | store_url }}\">{{ section.settings.ctaText }}</a>\n</section>\n</div>\n{% schema %}\n{\"name\":\"Call to Action\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Ready to get started?\",\"id\":\"heading\"},{\"type\":\"text\",\"label\":\"Subheading\",\"id\":\"subheading\"},{\"type\":\"text\",\"label\":\"Button text\",\"default\":\"Shop now\",\"id\":\"ctaText\"},{\"type\":\"url\",\"label\":\"Button link\",\"default\":\"/products\",\"id\":\"ctaLink\"}],\"blocks\":[],\"presets\":[{\"name\":\"Call to Action\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"customer-account":{"path":"sections/customer-account.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Customer Account","presets":[{"blocks":[],"name":"Customer Account","settings":{}}],"settings":[{"default":"Your account","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-account\" data-section-id=\"{{ section.id }}\">\n  {% if buyer %}\n  <h1>{{ section.settings.heading }}</h1>\n  <p class=\"lb-account__hello\">Signed in to LetBuyy as {{ buyer.full_name | default: buyer.email }}</p>\n  <nav class=\"lb-account__nav\"><a href=\"{{ routes.account_orders_url }}\">Orders</a><a href=\"{{ routes.account_addresses_url }}\">Addresses</a><a href=\"{{ routes.account_url }}/loyalty\">Rewards</a><a href=\"{{ routes.account_settings_url }}\">Settings</a><form method=\"post\" action=\"/api/buyer-auth/logout?return_to={{ routes.account_url }}\"><button type=\"submit\" class=\"lb-account__nav-link\">Sign out at this store</button></form></nav>\n  {% elsif buyer_unavailable %}<p class=\"lb-account__unavailable\" role=\"status\">We could not load your LetBuyy account right now. Please refresh and try again.</p>\n  {% elsif customer %}\n  <h1>{{ section.settings.heading }}</h1>\n  <p class=\"lb-account__hello\">Signed in as {{ customer.name | default: customer.email }}</p>\n  <nav class=\"lb-account__nav\"><a href=\"{{ routes.account_orders_url }}\">Orders</a><a href=\"{{ routes.account_addresses_url }}\">Addresses</a><a href=\"{{ routes.account_settings_url }}\">Settings</a><lb-logout data-logout-url=\"{{ routes.account_logout_url }}\"><form method=\"post\" action=\"{{ routes.account_logout_url }}\"><button type=\"submit\" class=\"lb-account__nav-link\">Sign out</button></form></lb-logout></nav>\n  {% else %}\n  <p class=\"lb-account__guest\">Please <a href=\"{{ routes.customer_login_url }}\">sign in</a> to view your account.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Customer Account\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Your account\",\"id\":\"heading\"}],\"blocks\":[],\"presets\":[{\"name\":\"Customer Account\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"customer-addresses":{"path":"sections/customer-addresses.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Addresses","presets":[{"blocks":[],"name":"Addresses","settings":{}}],"settings":[{"default":"Your addresses","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-addresses\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}</h1>\n  {% if buyer %}\n  <lb-address-manager data-lb-island=\"address-manager\" data-account-type=\"buyer\" data-base-path=\"/store/{{ shop.subdomain }}\" data-authenticated=\"true\"></lb-address-manager>\n  {% elsif buyer_unavailable %}<p class=\"lb-addresses__unavailable\" role=\"status\">We could not load your LetBuyy addresses right now. Please refresh and try again.</p>\n  {% elsif customer %}\n  {% if customer.addresses and customer.addresses.size > 0 %}\n  <div class=\"lb-addresses__grid\">\n    {% for addr in customer.addresses %}<div class=\"lb-address-card{% if addr.is_default %} lb-address-card--default{% endif %}\"><span class=\"lb-address-card__label\">{{ addr.label | default: \"address\" }}</span>{% if addr.is_default %}<span class=\"lb-address-card__default-badge\">Default</span>{% endif %}<p class=\"lb-address-card__address\">{{ addr.address1 }}{% if addr.address2 %}, {{ addr.address2 }}{% endif %}</p><p class=\"lb-address-card__city\">{{ addr.city }}, {{ addr.province }} {{ addr.zip }}</p></div>{% endfor %}\n  </div>\n  {% else %}\n  <p class=\"lb-addresses__empty\">No saved addresses.</p>\n  {% endif %}\n  <lb-address-manager\n    data-lb-island=\"address-manager\"\n    data-base-path=\"/store/{{ shop.subdomain }}\"\n    data-authenticated=\"true\"\n  ></lb-address-manager>\n  {% else %}\n  <p class=\"lb-addresses__guest\">Please <a href=\"{{ routes.customer_login_url }}\">sign in</a> to manage your addresses.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Addresses\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Your addresses\",\"id\":\"heading\"}],\"blocks\":[],\"presets\":[{\"name\":\"Addresses\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"customer-login":{"path":"sections/customer-login.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Customer Login","presets":[{"blocks":[],"name":"Customer Login","settings":{}}],"settings":[{"default":"Sign in","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-auth lb-auth--login\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}</h1>\n  {% if request.error %}<p class=\"lb-auth__error\" role=\"alert\">{% case request.error %}{% when \"missing_fields\" %}Please fill in all required fields.{% when \"invalid_credentials\" %}Incorrect email or password.{% when \"account_exists\" %}An account with this email already exists. Please sign in.{% when \"rate_limited\" %}Too many attempts. Please try again shortly.{% when \"bot_verification\" %}We could not verify you are not a robot. Please try again.{% else %}Something went wrong. Please try again.{% endcase %}</p>{% endif %}\n  <form class=\"lb-auth__form\" method=\"post\" action=\"/api/customer/login\">\n    <input type=\"hidden\" name=\"storeId\" value=\"{{ shop.id }}\">\n    <input type=\"hidden\" name=\"turnstileToken\" value=\"\">\n    <lb-turnstile data-lb-island=\"turnstile\"></lb-turnstile>\n    <label>Email<input type=\"email\" name=\"email\" autocomplete=\"email\" required></label>\n    <label>Password<input type=\"password\" name=\"password\" autocomplete=\"current-password\" required></label>\n    <button type=\"submit\">Sign in</button>\n  </form>\n  <a href=\"{{ routes.customer_register_url }}\">Create an account</a>\n  <p class=\"lb-auth__letbuyy\"><a href=\"/api/buyer-auth/start?return_to={{ routes.account_url }}\">Continue with LetBuyy</a></p>\n  <p>Have an older store account? Connect it with your verified LetBuyy account.</p>\n  <form class=\"lb-auth__link-store\" method=\"post\" action=\"/api/buyer-auth/start\">\n    <input type=\"hidden\" name=\"intent\" value=\"link_store_customer\">\n    <input type=\"hidden\" name=\"return_to\" value=\"{{ routes.account_url }}\">\n    <button type=\"submit\">Connect my store account</button>\n  </form>\n</section>\n</div>\n{% schema %}\n{\"name\":\"Customer Login\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Sign in\",\"id\":\"heading\"}],\"blocks\":[],\"presets\":[{\"name\":\"Customer Login\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"customer-order-detail":{"path":"sections/customer-order-detail.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Order Detail","presets":[{"blocks":[],"name":"Order Detail","settings":{}}],"settings":[{"default":"Order","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-order-detail\" data-section-id=\"{{ section.id }}\">\n  {% if buyer_unavailable %}<p class=\"lb-order-detail__error\" role=\"alert\">This order is temporarily unavailable. Please try again.</p>{% elsif buyer %}\n  {% if order %}\n  <h1>{{ section.settings.heading | strip | default: 'Order' }} #{{ order.number }}</h1>\n  <p class=\"lb-order-detail__status\">Status: {{ order.status }}</p>\n  <ul class=\"lb-order-detail__items\">{% for item in order.line_items %}<li><span class=\"lb-order-detail__title\">{{ item.title }}</span><span class=\"lb-order-detail__qty\">{{ item.quantity }}</span><span class=\"lb-order-detail__line\">{{ item.line_price | money_with_currency: order.currency }}</span><!-- lb:niche-order-presentation:v1 -->{% if item.niche_facts_text != blank %}<details class=\"lb-order-facts\"><summary>Saved product details</summary><p class=\"lb-order-facts__text\">{{ item.niche_facts_text }}</p></details>{% else %}<p class=\"lb-order-facts__missing\">Product details were not recorded with this order.</p>{% endif %}</li>{% endfor %}</ul>\n  <p class=\"lb-order-detail__total\">Total: {{ order.total | money_with_currency: order.currency }}</p>\n  {% if order.gst_invoice_number != blank %}<p class=\"lb-order-detail__invoice\">GST Invoice: {{ order.gst_invoice_number }} (Tax: {{ order.tax_total | money_with_currency: order.currency }})</p>{% endif %}\n  <ol class=\"lb-order-detail__timeline\">{% for step in order.timeline %}<li class=\"lb-order-detail__step{% if step.reached %} is-reached{% endif %}\">{{ step.label }}</li>{% endfor %}</ol>\n  {% if order.tracking_number != blank %}<p class=\"lb-order-detail__tracking\">Tracking: {{ order.tracking_number }}{% if order.carrier != blank %} ({{ order.carrier }}){% endif %}</p>{% endif %}\n  {% else %}<p class=\"lb-order-detail__missing\">Order not found.</p>{% endif %}\n  {% else %}<p class=\"lb-order-detail__guest\">Please <a href=\"/api/buyer-auth/start?return_to={{ routes.account_orders_url }}\">sign in with LetBuyy</a> to view this order.</p>{% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Order Detail\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Order\",\"id\":\"heading\"}],\"blocks\":[],\"presets\":[{\"name\":\"Order Detail\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"customer-orders":{"path":"sections/customer-orders.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Order History","presets":[{"blocks":[],"name":"Order History","settings":{}}],"settings":[{"default":"Your orders","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-orders\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}</h1>\n  {% if buyer_unavailable %}<p class=\"lb-orders__error\" role=\"alert\">Orders are temporarily unavailable. Please try again.</p>{% elsif buyer %}\n  <form class=\"lb-orders__claim\" method=\"post\" action=\"/api/buyer/orders\"><input type=\"hidden\" name=\"return_to\" value=\"{{ routes.account_orders_url }}\"><p>Find past orders from this store placed with your verified LetBuyy email.</p><button type=\"submit\">Find past orders</button></form>\n  {% if request.query.buyer_claim == \"complete\" %}<p role=\"status\" aria-live=\"polite\">The verified orders for this store have been checked and linked.</p>{% elsif request.query.buyer_claim == \"partial\" %}<p role=\"status\" aria-live=\"polite\">Some eligible orders could not be linked. Contact the store for help.</p>{% elsif request.query.buyer_claim == \"unverified\" %}<p role=\"status\" aria-live=\"polite\">Verify your LetBuyy email before claiming historical orders.</p>{% elsif request.query.buyer_claim == \"unavailable\" %}<p role=\"status\" aria-live=\"polite\">Historical orders could not be checked right now. Please try again.</p>{% elsif request.query.buyer_claim == \"unauthorized\" %}<p role=\"status\" aria-live=\"polite\">Sign in to LetBuyy before claiming past orders.</p>{% endif %}\n  {% if buyer.orders and buyer.orders.size > 0 %}\n  <ul class=\"lb-orders__list\">{% for order in buyer.orders %}<li class=\"lb-orders__row\"><a href=\"{{ routes.account_orders_url }}/{{ order.id }}\"><span class=\"lb-orders__num\">#{{ order.number }}</span><span class=\"lb-orders__status\">{{ order.status }}</span><span class=\"lb-orders__total\">{{ order.total | money_with_currency: order.currency }}</span></a></li>{% endfor %}</ul>\n  {% if buyer.has_more and buyer.next_cursor %}<a class=\"lb-orders__next\" href=\"{{ routes.account_orders_url }}?cursor={{ buyer.next_cursor }}\">Older orders</a>{% endif %}\n  {% else %}<p class=\"lb-orders__empty\">No orders yet.</p>{% endif %}\n  {% else %}\n  <p class=\"lb-orders__guest\">Please <a href=\"/api/buyer-auth/start?return_to={{ routes.account_orders_url }}\">sign in with LetBuyy</a> to view your orders.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Order History\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Your orders\",\"id\":\"heading\"}],\"blocks\":[],\"presets\":[{\"name\":\"Order History\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"customer-register":{"path":"sections/customer-register.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Customer Register","presets":[{"blocks":[],"name":"Customer Register","settings":{}}],"settings":[{"default":"Create account","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-auth lb-auth--register\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}</h1>\n  <p>Create one LetBuyy account to use across participating storefronts.</p>\n  <p class=\"lb-auth__letbuyy\"><a href=\"/api/buyer-auth/start?return_to={{ routes.account_url }}\">Create or sign in with LetBuyy</a></p>\n  <p>Have an older store-only account? <a href=\"{{ routes.customer_login_url }}\">Sign in to connect it with your verified LetBuyy account</a>.</p>\n</section>\n</div>\n{% schema %}\n{\"name\":\"Customer Register\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Create account\",\"id\":\"heading\"}],\"blocks\":[],\"presets\":[{\"name\":\"Customer Register\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"customer-settings":{"path":"sections/customer-settings.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Account Settings","presets":[{"blocks":[],"name":"Account Settings","settings":{}}],"settings":[{"default":"Account settings","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-settings\" data-section-id=\"{{ section.id }}\">\n  {% if buyer %}\n  <h1>{{ section.settings.heading }}</h1>\n  <div class=\"lb-settings__current\"><p class=\"lb-settings__email\">{{ buyer.email }}</p>{% if buyer.full_name %}<p class=\"lb-settings__name\">{{ buyer.full_name }}</p>{% endif %}{% if buyer.phone %}<p class=\"lb-settings__phone\">{{ buyer.phone }}</p>{% endif %}</div>\n  <lb-customer-settings data-lb-island=\"customer-settings\" data-account-type=\"buyer\" data-base-path=\"/store/{{ shop.subdomain }}\" data-authenticated=\"true\"></lb-customer-settings>\n  {% elsif buyer_unavailable %}<p class=\"lb-settings__unavailable\" role=\"status\">We could not load your LetBuyy profile right now. Please refresh and try again.</p>\n  {% elsif customer %}\n  <h1>{{ section.settings.heading }}</h1>\n  <div class=\"lb-settings__current\">\n    <p class=\"lb-settings__email\">{{ customer.email }}</p>\n    {% if customer.name %}<p class=\"lb-settings__name\">{{ customer.name }}</p>{% endif %}\n    {% if customer.phone %}<p class=\"lb-settings__phone\">{{ customer.phone }}</p>{% endif %}\n  </div>\n  <lb-customer-settings\n    data-lb-island=\"customer-settings\"\n    data-email=\"{{ customer.email | escape }}\"\n    data-name=\"{{ customer.name | default: \"\" | escape }}\"\n    data-phone=\"{{ customer.phone | default: \"\" | escape }}\"\n    data-base-path=\"/store/{{ shop.subdomain }}\"\n    data-authenticated=\"true\"\n  ></lb-customer-settings>\n  {% else %}\n  <p class=\"lb-settings__guest\">Please <a href=\"{{ routes.customer_login_url }}\">sign in</a> to manage your settings.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Account Settings\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Account settings\",\"id\":\"heading\"}],\"blocks\":[],\"presets\":[{\"name\":\"Account Settings\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"customer-wishlist":{"path":"sections/customer-wishlist.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Wishlist","presets":[{"blocks":[],"name":"Wishlist","settings":{}}],"settings":[{"default":"Your wishlist","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-wishlist\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}{% if customer.wishlist_products.size > 0 %} <span class=\"lb-wishlist__count\">({{ customer.wishlist_products.size }})</span>{% elsif buyer_wishlist.products.size > 0 %} <span class=\"lb-wishlist__count\">({{ buyer_wishlist.products.size }})</span>{% endif %}</h1>\n  {% if buyer_wishlist.authenticated %}\n    {% if buyer_wishlist.unavailable %}<p class=\"lb-wishlist__unavailable\" role=\"status\">Your wishlist is temporarily unavailable. Please try again.</p>\n    {% elsif buyer_wishlist.storeAccountUnavailable %}<p class=\"lb-wishlist__unavailable\" role=\"status\">This store account is unavailable. Contact the store for help.</p>\n    {% elsif buyer_wishlist.linked and buyer_wishlist.products.size > 0 %}\n      <div class=\"lb-product-grid__items\">{% for item in buyer_wishlist.products %}<article class=\"lb-product-card\"><a href=\"{{ item.url }}\"><strong>{{ item.title }}</strong><span>{{ item.price | times: 100 | money_with_currency: item.currency }}</span></a><lb-wishlist-toggle data-lb-island=\"wishlist-toggle\" data-product-id=\"{{ item.id }}\" data-store-id=\"{{ shop.id }}\" data-in-wishlist=\"true\" data-authenticated=\"true\" data-account-type=\"buyer\" data-buyer-id=\"{{ buyer_wishlist.buyerId }}\" data-buyer-linked=\"true\" data-base-path=\"/store/{{ shop.subdomain }}\"></lb-wishlist-toggle></article>{% endfor %}</div>\n    {% elsif buyer_wishlist.linked %}<p class=\"lb-wishlist__empty\">Your wishlist is empty. <a href=\"{{ routes.all_products_collection_url }}\">Browse products</a></p>\n    {% else %}<p class=\"lb-wishlist__guest\">Connect your verified store account in <a href=\"{{ routes.account_settings_url }}\">account settings</a> to use this store wishlist.</p>{% endif %}\n  {% elsif customer.wishlist_products and customer.wishlist_products.size > 0 %}\n  <div class=\"lb-product-grid__items\">\n    {% for item in customer.wishlist_products %}<article class=\"lb-product-card\"><a href=\"{{ item.url }}\"><strong>{{ item.title }}</strong><span>{{ item.price | times: 100 | money_with_currency: item.currency }}</span></a><lb-wishlist-toggle data-lb-island=\"wishlist-toggle\" data-product-id=\"{{ item.id }}\" data-store-id=\"{{ shop.id }}\" data-in-wishlist=\"true\" data-authenticated=\"true\" data-account-type=\"store_customer\" data-base-path=\"/store/{{ shop.subdomain }}\"></lb-wishlist-toggle></article>{% endfor %}\n  </div>\n  {% elsif customer %}\n  <p class=\"lb-wishlist__empty\">Your wishlist is empty. <a href=\"{{ routes.all_products_collection_url }}\">Browse products</a></p>\n  {% else %}\n  <p class=\"lb-wishlist__guest\">Please <a href=\"{{ routes.customer_login_url }}\">sign in</a> to view your wishlist.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Wishlist\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Your wishlist\",\"id\":\"heading\"}],\"blocks\":[],\"presets\":[{\"name\":\"Wishlist\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"experience-timeline":{"path":"sections/experience-timeline.liquid","schema":{"blocks":[{"name":"Experience","settings":[{"id":"title","label":"Title","type":"text"},{"id":"company","label":"Company","type":"text"},{"id":"period","label":"Period","type":"text"}],"type":"experience"}],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Experience Timeline","presets":[{"blocks":[],"name":"Experience Timeline","settings":{}}],"settings":[{"default":"Experience","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-experience-timeline\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% for block in section.blocks %}<article {{ block.editor_attributes | raw }}><h3>{{ block.settings.title }}</h3><p>{{ block.settings.company }}</p><time>{{ block.settings.period }}</time>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</article>{% endfor %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Experience Timeline\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Title\",\"default\":\"Experience\",\"id\":\"title\"}],\"blocks\":[{\"type\":\"experience\",\"name\":\"Experience\",\"settings\":[{\"type\":\"text\",\"label\":\"Title\",\"id\":\"title\"},{\"type\":\"text\",\"label\":\"Company\",\"id\":\"company\"},{\"type\":\"text\",\"label\":\"Period\",\"id\":\"period\"}]}],\"presets\":[{\"name\":\"Experience Timeline\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"faq-accordion":{"path":"sections/faq-accordion.liquid","schema":{"blocks":[{"name":"FAQ item","settings":[{"id":"question","label":"Question","type":"text"},{"id":"answer","label":"Answer","type":"richtext"}],"type":"faq-item"}],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"FAQ Accordion","presets":[{"blocks":[],"name":"FAQ Accordion","settings":{}}],"settings":[{"default":"Frequently asked questions","id":"title","label":"Title","type":"text"},{"default":false,"id":"allowMultipleOpen","label":"Allow multiple open","type":"toggle"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-faq-accordion\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% if section.blocks.size > 0 %}\n  <div class=\"lb-faq-accordion__items\">\n    {% for block in section.blocks %}<details {{ block.editor_attributes | raw }} class=\"lb-faq-accordion__item\"{% unless section.settings.allowMultipleOpen %} name=\"lb-faq-{{ section.id }}\"{% endunless %}><summary class=\"lb-faq-accordion__question\">{{ block.settings.question }}</summary><div class=\"lb-faq-accordion__answer\">{{ block.settings.answer }}</div>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</details>{% endfor %}\n  </div>\n  {% else %}\n  <p class=\"lb-faq-accordion__empty\">No questions published yet.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"FAQ Accordion\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Title\",\"default\":\"Frequently asked questions\",\"id\":\"title\"},{\"type\":\"toggle\",\"label\":\"Allow multiple open\",\"default\":false,\"id\":\"allowMultipleOpen\"}],\"blocks\":[{\"type\":\"faq-item\",\"name\":\"FAQ item\",\"settings\":[{\"type\":\"text\",\"label\":\"Question\",\"id\":\"question\"},{\"type\":\"richtext\",\"label\":\"Answer\",\"id\":\"answer\"}]}],\"presets\":[{\"name\":\"FAQ Accordion\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"featured-products":{"path":"sections/featured-products.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Independent related furniture","presets":[{"blocks":[],"name":"Independent related furniture","settings":{}}],"settings":[{"default":"In the same room","id":"title","label":"Heading","type":"text"},{"default":"Each piece is sold separately.","id":"subtitle","label":"Description","type":"text"},{"default":true,"id":"requireSelection","label":"Only show selected related products","type":"toggle"},{"id":"product1","label":"Independent product 1","type":"product"},{"id":"product2","label":"Independent product 2","type":"product"},{"id":"product3","label":"Independent product 3","type":"product"},{"default":2,"id":"productLimit","label":"Products to show","max":8,"min":1,"step":1,"type":"range"}],"tag":"section"},"source":"<section class=\"hab-theme\" data-section-id=\"{{ section.id }}\">{% if section.products.size > 0 %}<div class=\"hab-wrap hab-section\"><div class=\"hab-heading\"><div><span class=\"hab-eyebrow\">In the same room</span><h2>{{ section.settings.title }}</h2><p>{{ section.settings.subtitle }}</p></div></div><div class=\"hab-grid\">{% for item in section.products limit: section.settings.productLimit %}<article class=\"hab-card\"><a class=\"hab-card-image\" href=\"{{ item.url }}\">{% if item.featured_image != blank %}<img src=\"{{ item.featured_image | image_url }}\" alt=\"{{ item.title }}\" loading=\"lazy\" decoding=\"async\">{% else %}<span class=\"hab-placeholder\">Product photograph not supplied</span>{% endif %}{% if item.available == false %}<span class=\"hab-unavailable\">Unavailable</span>{% endif %}</a><div class=\"hab-card-heading\"><h3><a href=\"{{ item.url }}\">{{ item.title }}</a></h3><span class=\"hab-price\">{{ item.price | times: 100 | money_with_currency: item.currency }}</span></div>{% if item.furniture_display.assembled != blank %}<p class=\"hab-card-facts\">{{ item.furniture_display.assembled }}</p>{% elsif item.furniture.assembled != blank %}<p class=\"hab-card-facts\">{% if item.furniture.assembled.diameter %}{{ item.furniture.assembled.diameter }} Ø{% else %}{{ item.furniture.assembled.width | default: '—' }} W × {{ item.furniture.assembled.depth | default: '—' }} D{% endif %}{% if item.furniture.assembled.height %} × {{ item.furniture.assembled.height }} H{% endif %} {{ item.furniture.assembled.unit }}</p>{% else %}<p class=\"hab-card-facts\">Dimensions not supplied</p>{% endif %}{% if item.furniture.finish != blank %}<p class=\"hab-card-facts\">{{ item.furniture.finish }}</p>{% else %}{% for option in item.option_summaries %}<p class=\"hab-card-facts\">{{ option.name }}: {{ option.summary }}</p>{% endfor %}{% endif %}<a class=\"hab-link\" href=\"{{ item.url }}\">View dimensions &amp; options <span aria-hidden=\"true\">→</span></a></article>{% endfor %}</div></div>{% endif %}</section>\n{% schema %}\n{\"name\":\"Independent related furniture\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"In the same room\",\"id\":\"title\"},{\"type\":\"text\",\"label\":\"Description\",\"default\":\"Each piece is sold separately.\",\"id\":\"subtitle\"},{\"type\":\"toggle\",\"label\":\"Only show selected related products\",\"default\":true,\"id\":\"requireSelection\"},{\"type\":\"product\",\"label\":\"Independent product 1\",\"id\":\"product1\"},{\"type\":\"product\",\"label\":\"Independent product 2\",\"id\":\"product2\"},{\"type\":\"product\",\"label\":\"Independent product 3\",\"id\":\"product3\"},{\"type\":\"range\",\"label\":\"Products to show\",\"default\":2,\"min\":1,\"max\":8,\"step\":1,\"id\":\"productLimit\"}],\"blocks\":[],\"presets\":[{\"name\":\"Independent related furniture\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"footer":{"path":"sections/footer.liquid","schema":{"blocks":[{"name":"Link","settings":[{"id":"label","label":"Label","type":"text"},{"id":"href","label":"URL","type":"url"}],"type":"link"}],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Footer","presets":[{"blocks":[],"name":"Footer","settings":{}}],"settings":[{"id":"storeName","label":"Store name","type":"text"},{"id":"tagline","label":"Tagline","type":"text"},{"id":"contactEmail","label":"Contact email","type":"text"},{"id":"contactPhone","label":"Contact phone","type":"text"},{"id":"instagramUrl","label":"Instagram URL","type":"url"},{"id":"facebookUrl","label":"Facebook URL","type":"url"},{"id":"twitterUrl","label":"Twitter/X URL","type":"url"}],"tag":"section"},"source":"<div class=\"hab-theme\"><footer class=\"lb-footer\" data-section-id=\"{{ section.id }}\">\n  <div class=\"lb-footer__grid\">\n    <div class=\"lb-footer__brand\">\n      <h3>{{ section.settings.storeName | default: shop.name }}</h3>\n      {% if section.settings.tagline %}<p>{{ section.settings.tagline }}</p>{% endif %}\n      {% if section.settings.instagramUrl != blank or section.settings.facebookUrl != blank or section.settings.twitterUrl != blank %}\n      <div class=\"lb-footer__social\">\n        {% if section.settings.instagramUrl != blank %}<a href=\"{{ section.settings.instagramUrl }}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Instagram\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\" ry=\"5\"></rect><circle cx=\"12\" cy=\"12\" r=\"4\"></circle><circle cx=\"17.5\" cy=\"6.5\" r=\"1\"></circle></svg></a>{% endif %}\n        {% if section.settings.facebookUrl != blank %}<a href=\"{{ section.settings.facebookUrl }}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Facebook\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M15 4h-2a4 4 0 0 0-4 4v3H6v4h3v7h4v-7h3l1-4h-4V8a1 1 0 0 1 1-1h3z\"></path></svg></a>{% endif %}\n        {% if section.settings.twitterUrl != blank %}<a href=\"{{ section.settings.twitterUrl }}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Twitter/X\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><line x1=\"4\" y1=\"4\" x2=\"20\" y2=\"20\"></line><line x1=\"20\" y1=\"4\" x2=\"4\" y2=\"20\"></line></svg></a>{% endif %}\n      </div>\n      {% endif %}\n    </div>\n    {% if section.blocks.size > 0 %}\n    <div class=\"lb-footer__col\"><h4>Quick links</h4><nav>{% for block in section.blocks %}<a {{ block.editor_attributes | raw }} href=\"{{ block.settings.href | store_url }}\">{{ block.settings.label }}{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</a>{% endfor %}</nav></div>\n    {% elsif linklists.footer_menu.links.size > 0 %}\n    <div class=\"lb-footer__col\"><h4>Quick links</h4><nav>{% for link in linklists.footer_menu.links %}<a href=\"{{ link.url | store_url }}\"{% if link.active %} aria-current=\"page\"{% endif %}>{{ link.title }}</a>{% endfor %}</nav></div>\n    {% endif %}\n    {% if shop.policies.size > 0 %}<div class=\"lb-footer__col\">\n      <h4>Policies</h4>\n      <nav>\n        {% if shop.policies contains 'privacy' %}<a href=\"{{ routes.root_url }}/privacy\">Privacy policy</a>{% endif %}\n        {% if shop.policies contains 'terms' %}<a href=\"{{ routes.root_url }}/terms\">Terms of service</a>{% endif %}\n        {% if shop.policies contains 'shipping' %}<a href=\"{{ routes.root_url }}/shipping\">Shipping policy</a>{% endif %}\n        {% if shop.policies contains 'refund' or shop.policies contains 'returns' %}<a href=\"{{ routes.root_url }}/returns\">Returns policy</a>{% endif %}\n      </nav>\n    </div>{% endif %}\n    <div class=\"lb-footer__col\">\n      <h4>Contact</h4>\n      {% if section.settings.contactEmail != blank %}<p><a href=\"mailto:{{ section.settings.contactEmail }}\">{{ section.settings.contactEmail }}</a></p>{% endif %}\n      {% if section.settings.contactPhone != blank %}<p><a href=\"tel:{{ section.settings.contactPhone }}\">{{ section.settings.contactPhone }}</a></p>{% endif %}\n      <a href=\"{{ routes.contact_url }}\">Contact us</a>\n    </div>\n  </div>\n  <div class=\"lb-footer__bottom\">\n    <p>&copy; {{ shop.name }}. All rights reserved.</p>\n    <a class=\"lb-footer__watermark\" href=\"https://letbuyy.com\" target=\"_blank\" rel=\"noopener noreferrer\">Powered by LetBuyy</a>\n  </div>\n</footer>\n</div>\n{% schema %}\n{\"name\":\"Footer\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Store name\",\"id\":\"storeName\"},{\"type\":\"text\",\"label\":\"Tagline\",\"id\":\"tagline\"},{\"type\":\"text\",\"label\":\"Contact email\",\"id\":\"contactEmail\"},{\"type\":\"text\",\"label\":\"Contact phone\",\"id\":\"contactPhone\"},{\"type\":\"url\",\"label\":\"Instagram URL\",\"id\":\"instagramUrl\"},{\"type\":\"url\",\"label\":\"Facebook URL\",\"id\":\"facebookUrl\"},{\"type\":\"url\",\"label\":\"Twitter/X URL\",\"id\":\"twitterUrl\"}],\"blocks\":[{\"type\":\"link\",\"name\":\"Link\",\"settings\":[{\"type\":\"text\",\"label\":\"Label\",\"id\":\"label\"},{\"type\":\"url\",\"label\":\"URL\",\"id\":\"href\"}]}],\"presets\":[{\"name\":\"Footer\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"habitat-measurement-guide":{"path":"sections/habitat-measurement-guide.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Measurement guide","presets":[{"blocks":[],"name":"Measurement guide","settings":{}}],"settings":[{"default":"Before you bring it home","id":"eyebrow","label":"Eyebrow","type":"text"},{"default":"Measure twice. Make room once.","id":"title","label":"Heading","type":"text"},{"default":"Check the furniture footprint and the route it will take to reach your room.","id":"description","label":"Description","type":"text"},{"default":"Map your room","id":"step1Title","label":"First step","type":"text"},{"default":"Mark the supplied width and depth. Keep your own circulation space.","id":"step1Text","label":"First guidance","type":"text"},{"default":"Follow the access path","id":"step2Title","label":"Second step","type":"text"},{"default":"Measure doors, stair turns and lifts against package dimensions.","id":"step2Text","label":"Second guidance","type":"text"},{"default":"Check delivery conditions","id":"step3Title","label":"Third step","type":"text"},{"default":"Read the merchant’s actual service terms before checkout.","id":"step3Text","label":"Third guidance","type":"text"}],"tag":"section"},"source":"<section class=\"hab-theme\" data-section-id=\"{{ section.id }}\"><div class=\"hab-wrap hab-section\"><div class=\"hab-education\"><div><span class=\"hab-eyebrow\">{{ section.settings.eyebrow }}</span><h2>{{ section.settings.title }}</h2><p>{{ section.settings.description }}</p></div><ol class=\"hab-steps\">{% for step in (1..3) %}{% assign title_key = 'step' | append: step | append: 'Title' %}{% assign text_key = 'step' | append: step | append: 'Text' %}{% if section.settings[title_key] != blank %}<li><span aria-hidden=\"true\">0{{ step }}</span><div><h3>{{ section.settings[title_key] }}</h3><p>{{ section.settings[text_key] }}</p></div></li>{% endif %}{% endfor %}</ol></div></div></section>\n{% schema %}\n{\"name\":\"Measurement guide\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Eyebrow\",\"default\":\"Before you bring it home\",\"id\":\"eyebrow\"},{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Measure twice. Make room once.\",\"id\":\"title\"},{\"type\":\"text\",\"label\":\"Description\",\"default\":\"Check the furniture footprint and the route it will take to reach your room.\",\"id\":\"description\"},{\"type\":\"text\",\"label\":\"First step\",\"default\":\"Map your room\",\"id\":\"step1Title\"},{\"type\":\"text\",\"label\":\"First guidance\",\"default\":\"Mark the supplied width and depth. Keep your own circulation space.\",\"id\":\"step1Text\"},{\"type\":\"text\",\"label\":\"Second step\",\"default\":\"Follow the access path\",\"id\":\"step2Title\"},{\"type\":\"text\",\"label\":\"Second guidance\",\"default\":\"Measure doors, stair turns and lifts against package dimensions.\",\"id\":\"step2Text\"},{\"type\":\"text\",\"label\":\"Third step\",\"default\":\"Check delivery conditions\",\"id\":\"step3Title\"},{\"type\":\"text\",\"label\":\"Third guidance\",\"default\":\"Read the merchant’s actual service terms before checkout.\",\"id\":\"step3Text\"}],\"blocks\":[],\"presets\":[{\"name\":\"Measurement guide\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"header":{"path":"sections/header.liquid","schema":{"blocks":[{"name":"Link","settings":[{"id":"label","label":"Label","type":"text"},{"id":"href","label":"URL","type":"url"}],"type":"link"}],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Header","presets":[{"blocks":[],"name":"Header","settings":{}}],"settings":[{"id":"storeName","label":"Store name","type":"text"},{"default":true,"id":"showSearch","label":"Show search","type":"toggle"},{"default":true,"id":"showCart","label":"Show cart","type":"toggle"},{"default":"sticky","id":"behavior","label":"Header behavior","options":["static","sticky"],"type":"select"},{"default":"main_menu","id":"menu","label":"Menu","options":["main_menu","footer_menu","policy_menu"],"type":"select"},{"default":"inline","id":"layout","label":"Layout","options":["inline","centered"],"type":"select"}],"tag":"section"},"source":"<div class=\"hab-theme\"><header class=\"lb-header\" data-section-id=\"{{ section.id }}\" data-sticky=\"{% if section.settings.behavior == 'sticky' %}true{% else %}false{% endif %}\" data-layout=\"{{ section.settings.layout | default: 'inline' }}\">\n  <div class=\"lb-header__inner\">\n    <lb-mobile-nav class=\"lb-mobile-nav\" data-lb-island=\"mobile-nav\">\n      <button type=\"button\" class=\"lb-header__toggle\" data-lb-nav-toggle aria-expanded=\"false\" aria-controls=\"lb-nav-panel-{{ section.id }}\" aria-label=\"Menu\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><line x1=\"3\" y1=\"6\" x2=\"21\" y2=\"6\"></line><line x1=\"3\" y1=\"12\" x2=\"21\" y2=\"12\"></line><line x1=\"3\" y1=\"18\" x2=\"21\" y2=\"18\"></line></svg><span class=\"lb-sr-only\">Menu</span></button>\n      <nav class=\"lb-header__nav\" data-lb-nav-panel id=\"lb-nav-panel-{{ section.id }}\" aria-label=\"Primary\">\n        <div class=\"lb-header__nav-head\"><span class=\"lb-header__nav-head-brand\">{{ section.settings.storeName | default: shop.name }}</span><button type=\"button\" class=\"lb-header__nav-close\" data-lb-nav-close aria-label=\"Close menu\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><line x1=\"5\" y1=\"5\" x2=\"19\" y2=\"19\"></line><line x1=\"19\" y1=\"5\" x2=\"5\" y2=\"19\"></line></svg><span class=\"lb-sr-only\">Close menu</span></button></div>\n        <div class=\"lb-header__nav-links\">\n        {% if section.blocks.size > 0 %}\n          {% for block in section.blocks %}<a {{ block.editor_attributes | raw }} href=\"{{ block.settings.href | store_url }}\">{{ block.settings.label }}{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</a>{% endfor %}\n        {% else %}\n          {% assign lb_menu_handle = section.settings.menu | default: 'main_menu' %}\n          {% assign lb_nav_links = linklists[lb_menu_handle].links %}\n          {% for link in lb_nav_links %}\n            {% if link.links.size > 0 %}\n            <details class=\"lb-header__nav-item\" data-lb-nav-dropdown><summary{% if link.active %} aria-current=\"page\"{% endif %}>{{ link.title }}<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\" class=\"lb-icon-chevron\"><path d=\"M6 9l6 6 6-6\"></path></svg></summary>\n              <div class=\"lb-header__nav-submenu\">{% for child in link.links %}<a href=\"{{ child.url | store_url }}\"{% if child.active %} aria-current=\"page\"{% endif %}>{{ child.title }}</a>{% endfor %}</div>\n            </details>\n            {% else %}<a href=\"{{ link.url | store_url }}\"{% if link.active %} aria-current=\"page\"{% endif %}>{{ link.title }}</a>{% endif %}\n          {% endfor %}\n        {% endif %}\n        </div>\n        <div class=\"lb-header__nav-foot\">\n          {% if customer %}<a href=\"{{ routes.account_url }}\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"12\" cy=\"8\" r=\"4\"></circle><path d=\"M4 20c0-4 4-6 8-6s8 2 8 6\"></path></svg><span>Account</span></a>{% else %}<a href=\"{{ routes.customer_login_url }}\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"12\" cy=\"8\" r=\"4\"></circle><path d=\"M4 20c0-4 4-6 8-6s8 2 8 6\"></path></svg><span>Log in</span></a>{% endif %}\n        </div>\n      </nav>\n      <div class=\"lb-header__scrim\" data-lb-nav-scrim></div>\n    </lb-mobile-nav>\n    <a class=\"lb-header__brand\" href=\"{{ routes.root_url }}\">\n      {% if shop.logo_url %}<img class=\"lb-header__logo\" src=\"{{ shop.logo_url | image_url }}\" alt=\"{{ section.settings.storeName | default: shop.name }}\">{% else %}{{ section.settings.storeName | default: shop.name }}{% endif %}\n    </a>\n    <div class=\"lb-header__actions\">\n      {% if section.settings.showSearch %}<button type=\"button\" class=\"lb-header__search-toggle\" data-lb-search-toggle aria-expanded=\"false\" aria-controls=\"lb-search-overlay-{{ section.id }}\" aria-label=\"Search\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"11\" cy=\"11\" r=\"8\"></circle><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line></svg><span class=\"lb-sr-only\">Search</span></button>{% endif %}\n      <a class=\"lb-header__account\" href=\"{% if customer %}{{ routes.account_url }}{% else %}{{ routes.customer_login_url }}{% endif %}\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"12\" cy=\"8\" r=\"4\"></circle><path d=\"M4 20c0-4 4-6 8-6s8 2 8 6\"></path></svg><span class=\"lb-sr-only\">{% if customer %}Account{% else %}Log in{% endif %}</span></a>\n      {% if section.settings.showCart %}<a class=\"lb-header__cart\" href=\"{{ routes.cart_url }}\" data-lb-cart-trigger><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M3 4h2l2 12h11l2-8H6\"></path><circle cx=\"9\" cy=\"20\" r=\"1\"></circle><circle cx=\"17\" cy=\"20\" r=\"1\"></circle></svg><span class=\"lb-sr-only\">{{ \"general.cart\" | t }}</span> (<span data-lb-cart-count>{{ cart.item_count | default: 0 }}</span>)</a>{% endif %}\n    </div>\n  </div>\n  {% if section.settings.showSearch %}\n  <div class=\"lb-header__search-overlay\" id=\"lb-search-overlay-{{ section.id }}\" data-lb-search-overlay hidden>\n    <lb-predictive-search class=\"lb-predictive-search\" data-lb-island=\"predictive-search\" data-search-url=\"{{ routes.search_url }}\">\n      <form role=\"search\" method=\"get\" action=\"{{ routes.search_url }}\" data-lb-search-form>\n        <label class=\"lb-sr-only\" for=\"lb-search-input-{{ section.id }}\">Search products</label>\n        <input type=\"search\" name=\"search\" id=\"lb-search-input-{{ section.id }}\" data-lb-search-input placeholder=\"Search products\" autocomplete=\"off\" role=\"combobox\" aria-expanded=\"false\" aria-controls=\"lb-search-results-{{ section.id }}\" aria-autocomplete=\"list\">\n        <button type=\"submit\" aria-label=\"Search\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"11\" cy=\"11\" r=\"8\"></circle><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line></svg><span class=\"lb-sr-only\">Search</span></button>\n        <button type=\"button\" data-lb-search-close aria-label=\"Close search\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><line x1=\"5\" y1=\"5\" x2=\"19\" y2=\"19\"></line><line x1=\"19\" y1=\"5\" x2=\"5\" y2=\"19\"></line></svg><span class=\"lb-sr-only\">Close search</span></button>\n      </form>\n      <div id=\"lb-search-results-{{ section.id }}\" class=\"lb-predictive-search__results\" data-lb-search-results role=\"listbox\" aria-live=\"polite\"></div>\n    </lb-predictive-search>\n  </div>\n  {% endif %}\n</header>\n</div>\n{% schema %}\n{\"name\":\"Header\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Store name\",\"id\":\"storeName\"},{\"type\":\"toggle\",\"label\":\"Show search\",\"default\":true,\"id\":\"showSearch\"},{\"type\":\"toggle\",\"label\":\"Show cart\",\"default\":true,\"id\":\"showCart\"},{\"type\":\"select\",\"label\":\"Header behavior\",\"default\":\"sticky\",\"options\":[\"static\",\"sticky\"],\"id\":\"behavior\"},{\"type\":\"select\",\"label\":\"Menu\",\"default\":\"main_menu\",\"options\":[\"main_menu\",\"footer_menu\",\"policy_menu\"],\"id\":\"menu\"},{\"type\":\"select\",\"label\":\"Layout\",\"default\":\"inline\",\"options\":[\"inline\",\"centered\"],\"id\":\"layout\"}],\"blocks\":[{\"type\":\"link\",\"name\":\"Link\",\"settings\":[{\"type\":\"text\",\"label\":\"Label\",\"id\":\"label\"},{\"type\":\"url\",\"label\":\"URL\",\"id\":\"href\"}]}],\"presets\":[{\"name\":\"Header\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"hero-banner":{"path":"sections/hero-banner.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Room index and panorama","presets":[{"blocks":[],"name":"Room index and panorama","settings":{}}],"settings":[{"default":"The considered home","id":"eyebrow","label":"Eyebrow","type":"text"},{"default":"A little room. A lot of living.","id":"heading","label":"Heading","type":"text"},{"default":"Find furniture for your space, with the dimensions and details to make it yours.","id":"subheading","label":"Description","type":"text"},{"default":"Start with a room","id":"roomIndexLabel","label":"Room index label","type":"text"},{"id":"collection1","label":"Room collection 1","type":"collection"},{"id":"collection2","label":"Room collection 2","type":"collection"},{"id":"collection3","label":"Room collection 3","type":"collection"},{"id":"collection4","label":"Room collection 4","type":"collection"},{"id":"image","label":"Room panorama","type":"image"},{"default":"","id":"imageAlt","label":"Room photograph description","type":"text"},{"default":"","id":"caption","label":"Panorama caption","type":"text"},{"default":"Explore furniture","id":"ctaText","label":"Primary link","type":"text"},{"default":"/products","id":"ctaLink","label":"Primary destination","type":"url"},{"default":"","id":"guideText","label":"Guide link","type":"text"},{"default":"","id":"guideLink","label":"Guide destination","type":"url"},{"default":"center","id":"imageFocus","label":"Panorama focal position","options":["center","top","bottom"],"type":"select"}],"tag":"section"},"source":"<section class=\"hab-theme{% if section.settings.image == blank %} hab-hero-empty{% endif %}\" data-section-id=\"{{ section.id }}\"><div class=\"hab-wrap\"><div class=\"hab-hero-heading\"><div><span class=\"hab-eyebrow\">{{ section.settings.eyebrow }}</span><h1>{{ section.settings.heading }}</h1></div><p>{{ section.settings.subheading }}</p></div><div class=\"hab-room-story\"><nav class=\"hab-room-index\" aria-label=\"Room collections\"><span class=\"hab-eyebrow\">{{ section.settings.roomIndexLabel }}</span>{% assign has_room_selection = false %}{% if section.settings.collection1 != blank or section.settings.collection2 != blank or section.settings.collection3 != blank or section.settings.collection4 != blank %}{% assign has_room_selection = true %}{% endif %}{% if has_room_selection %}{% for slot in (1..4) %}{% assign room_key = 'collection' | append: slot %}{% assign room_id = section.settings[room_key] %}{% if room_id != blank %}{% for room in collections limit: 100 %}{% if room.id == room_id or room.handle == room_id %}<a href=\"{{ routes.collections_url }}/{{ room.handle }}\">{{ room.title }} <span aria-hidden=\"true\">→</span></a>{% endif %}{% endfor %}{% endif %}{% endfor %}{% elsif collections.size > 0 %}{% for room in collections limit: 4 %}<a href=\"{{ routes.collections_url }}/{{ room.handle }}\">{{ room.title }} <span aria-hidden=\"true\">→</span></a>{% endfor %}{% else %}<p class=\"hab-support\">Collections supplied by this store will appear here.</p>{% endif %}</nav>{% if section.settings.image != blank %}<div class=\"hab-room-media hab-focus-{{ section.settings.imageFocus }}\"><img src=\"{{ section.settings.image | image_url }}\" alt=\"{{ section.settings.imageAlt }}\" fetchpriority=\"high\" decoding=\"async\"><div class=\"hab-room-caption\">{% if section.settings.caption != blank %}<span>{{ section.settings.caption }}</span>{% endif %}{% if section.settings.ctaText != blank and section.settings.ctaLink != blank %}<a class=\"hab-link\" href=\"{{ section.settings.ctaLink | store_url }}\">{{ section.settings.ctaText }} →</a>{% endif %}</div></div>{% endif %}</div><div class=\"hab-guide-strip\"><p>Start with the space you have.<br><span class=\"hab-support\">Room dimensions, doorways and access matter.</span></p>{% if section.settings.guideText != blank and section.settings.guideLink != blank %}<a class=\"hab-link\" href=\"{{ section.settings.guideLink | store_url }}\">{{ section.settings.guideText }}</a>{% endif %}{% if section.settings.image == blank and section.settings.ctaLink != blank %}<a class=\"hab-link\" href=\"{{ section.settings.ctaLink | store_url }}\">{{ section.settings.ctaText }}</a>{% endif %}</div></div></section>\n{% schema %}\n{\"name\":\"Room index and panorama\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Eyebrow\",\"default\":\"The considered home\",\"id\":\"eyebrow\"},{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"A little room. A lot of living.\",\"id\":\"heading\"},{\"type\":\"text\",\"label\":\"Description\",\"default\":\"Find furniture for your space, with the dimensions and details to make it yours.\",\"id\":\"subheading\"},{\"type\":\"text\",\"label\":\"Room index label\",\"default\":\"Start with a room\",\"id\":\"roomIndexLabel\"},{\"type\":\"collection\",\"label\":\"Room collection 1\",\"id\":\"collection1\"},{\"type\":\"collection\",\"label\":\"Room collection 2\",\"id\":\"collection2\"},{\"type\":\"collection\",\"label\":\"Room collection 3\",\"id\":\"collection3\"},{\"type\":\"collection\",\"label\":\"Room collection 4\",\"id\":\"collection4\"},{\"type\":\"image\",\"label\":\"Room panorama\",\"id\":\"image\"},{\"type\":\"text\",\"label\":\"Room photograph description\",\"default\":\"\",\"id\":\"imageAlt\"},{\"type\":\"text\",\"label\":\"Panorama caption\",\"default\":\"\",\"id\":\"caption\"},{\"type\":\"text\",\"label\":\"Primary link\",\"default\":\"Explore furniture\",\"id\":\"ctaText\"},{\"type\":\"url\",\"label\":\"Primary destination\",\"default\":\"/products\",\"id\":\"ctaLink\"},{\"type\":\"text\",\"label\":\"Guide link\",\"default\":\"\",\"id\":\"guideText\"},{\"type\":\"url\",\"label\":\"Guide destination\",\"default\":\"\",\"id\":\"guideLink\"},{\"type\":\"select\",\"label\":\"Panorama focal position\",\"default\":\"center\",\"options\":[\"center\",\"top\",\"bottom\"],\"id\":\"imageFocus\"}],\"blocks\":[],\"presets\":[{\"name\":\"Room index and panorama\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"marquee":{"path":"sections/marquee.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Marquee","presets":[{"blocks":[],"name":"Marquee","settings":{}}],"settings":[{"default":"Featured announcement","id":"text","label":"Text","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-marquee\" data-section-id=\"{{ section.id }}\">\n  <p>{{ section.settings.text }}</p>\n</section>\n</div>\n{% schema %}\n{\"name\":\"Marquee\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Text\",\"default\":\"Featured announcement\",\"id\":\"text\"}],\"blocks\":[],\"presets\":[{\"name\":\"Marquee\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"newsletter-signup":{"path":"sections/newsletter-signup.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Newsletter Signup","presets":[{"blocks":[],"name":"Newsletter Signup","settings":{}}],"settings":[{"default":"Get first access","id":"title","label":"Heading","type":"text"},{"id":"subtitle","label":"Subheading","type":"text"},{"default":"Sign up","id":"buttonLabel","label":"Button label","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-newsletter-signup\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  <p>{{ section.settings.subtitle }}</p>\n  <form action=\"/contact\" method=\"post\">\n    <input type=\"email\" name=\"email\" aria-label=\"Email\" required>\n    <button type=\"submit\">{{ section.settings.buttonLabel }}</button>\n  </form>\n</section>\n</div>\n{% schema %}\n{\"name\":\"Newsletter Signup\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Get first access\",\"id\":\"title\"},{\"type\":\"text\",\"label\":\"Subheading\",\"id\":\"subtitle\"},{\"type\":\"text\",\"label\":\"Button label\",\"default\":\"Sign up\",\"id\":\"buttonLabel\"}],\"blocks\":[],\"presets\":[{\"name\":\"Newsletter Signup\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"page-content":{"path":"sections/page-content.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Page Content","presets":[{"blocks":[],"name":"Page Content","settings":{}}],"settings":[],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-page\" data-section-id=\"{{ section.id }}\">\n  {% if page %}\n  <h1 class=\"lb-page__title\">{{ page.title }}</h1>\n  {% if page.body_html != blank %}<div class=\"lb-page__body\">{{ page.body_html | raw }}</div>\n  {% else %}<p class=\"lb-page__empty\">No content yet.</p>{% endif %}\n  {% else %}\n  <p class=\"lb-page__missing\">Page not found.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Page Content\",\"tag\":\"section\",\"settings\":[],\"blocks\":[],\"presets\":[{\"name\":\"Page Content\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"password-gate":{"path":"sections/password-gate.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Password Gate","presets":[{"blocks":[],"name":"Password Gate","settings":{}}],"settings":[{"default":"Coming Soon","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><!-- password gate rendering requires proxy routing update (Phase F) -->\n<section class=\"lb-password-gate\" data-section-id=\"{{ section.id }}\">\n  <h1 class=\"lb-password-gate__heading\">{{ shop.name }}</h1>\n  <p class=\"lb-password-gate__message\">{{ section.settings.heading }}</p>\n  <p class=\"lb-password-gate__info\">This store is password protected.</p>\n  <form class=\"lb-password-gate__form\" method=\"post\" action=\"/store-access/password\">\n    <label class=\"lb-password-gate__label\">Enter password<input class=\"lb-password-gate__input\" type=\"password\" name=\"password\" autocomplete=\"current-password\" required></label>\n    <button type=\"submit\" class=\"lb-password-gate__btn\">Enter</button>\n  </form>\n  {% if shop.access_message and shop.access_message != blank %}<p class=\"lb-password-gate__access-message\">{{ shop.access_message }}</p>{% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Password Gate\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Coming Soon\",\"id\":\"heading\"}],\"blocks\":[],\"presets\":[{\"name\":\"Password Gate\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"policy-content":{"path":"sections/policy-content.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Policy Content","presets":[{"blocks":[],"name":"Policy Content","settings":{}}],"settings":[],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-policy\" data-section-id=\"{{ section.id }}\">\n  {% if page %}\n  <h1 class=\"lb-policy__title\">{{ page.title }}</h1>\n  {% if page.body_html != blank %}<div class=\"lb-policy__body\">{{ page.body_html | raw }}</div>\n  {% elsif page.content != blank %}<div class=\"lb-policy__body\">{{ page.content | raw }}</div>{% endif %}\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Policy Content\",\"tag\":\"section\",\"settings\":[],\"blocks\":[],\"presets\":[{\"name\":\"Policy Content\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"portfolio-grid":{"path":"sections/portfolio-grid.liquid","schema":{"blocks":[{"name":"Project","settings":[{"id":"title","label":"Title","type":"text"},{"id":"summary","label":"Summary","type":"textarea"},{"id":"link","label":"Link","type":"url"}],"type":"project"}],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Portfolio Grid","presets":[{"blocks":[],"name":"Portfolio Grid","settings":{}}],"settings":[{"default":"Portfolio","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-portfolio-grid\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% for block in section.blocks %}<article {{ block.editor_attributes | raw }}><h3>{{ block.settings.title }}</h3><p>{{ block.settings.summary }}</p><a href=\"{{ block.settings.link | store_url }}\">View</a>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</article>{% endfor %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Portfolio Grid\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Title\",\"default\":\"Portfolio\",\"id\":\"title\"}],\"blocks\":[{\"type\":\"project\",\"name\":\"Project\",\"settings\":[{\"type\":\"text\",\"label\":\"Title\",\"id\":\"title\"},{\"type\":\"textarea\",\"label\":\"Summary\",\"id\":\"summary\"},{\"type\":\"url\",\"label\":\"Link\",\"id\":\"link\"}]}],\"presets\":[{\"name\":\"Portfolio Grid\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"product-detail":{"path":"sections/product-detail.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Product Detail","presets":[{"blocks":[],"name":"Product Detail","settings":{}}],"settings":[{"default":true,"id":"showGallery","label":"Show gallery","type":"toggle"},{"default":true,"id":"showDescription","label":"Show description","type":"toggle"},{"default":true,"id":"showReviews","label":"Show reviews","type":"toggle"},{"default":false,"id":"showBuyNow","label":"Show buy now","type":"toggle"},{"default":true,"id":"showFurnitureFacts","label":"Show furniture facts","type":"toggle"},{"default":true,"id":"showDimensionDiagram","label":"Show supplied footprint schematic","type":"toggle"},{"default":false,"id":"showRoomContext","label":"Use the selected product image position as room context","type":"toggle"},{"default":"Know every dimension.","id":"factsHeading","label":"Facts heading","type":"text"},{"default":2,"id":"contextMediaIndex","label":"Room context image position (if supplied)","max":20,"min":1,"step":1,"type":"range"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-product-detail\" data-section-id=\"{{ section.id }}\">\n  <nav class=\"lb-product-detail__breadcrumb\" aria-label=\"Breadcrumb\">\n    <a href=\"{{ routes.root_url }}\">Home</a>\n    <a href=\"{{ routes.all_products_collection_url }}\">Shop</a>\n    <span aria-current=\"page\">{{ product.title }}</span>\n  </nav>\n  {% assign context_index = section.settings.contextMediaIndex | minus: 1 %}{% assign context_image = product.images[context_index] %}{% if section.settings.showRoomContext and context_image != blank %}<figure class=\"hab-pdp-room\"><img src=\"{{ context_image | image_url }}\" alt=\"{{ product.title }} · supplied room context\" decoding=\"async\"><figcaption>Room context. Other objects are sold separately unless listed in this product’s contents.</figcaption></figure>{% endif %}\n  <div class=\"lb-product-detail__layout\">\n  {% if section.settings.showGallery and product.images.size > 0 %}\n  <lb-product-gallery class=\"lb-product-detail__gallery\" data-lb-island=\"product-gallery\">\n    <div class=\"lb-product-detail__gallery-main\">\n      {% for image in product.images %}<img class=\"lb-product-detail__gallery-image\" src=\"{{ image | image_url }}\" alt=\"{{ product.title }}\" data-lb-gallery-image data-index=\"{{ forloop.index0 }}\"{% unless forloop.first %} hidden{% endunless %} loading=\"{% if forloop.first %}eager{% else %}lazy{% endif %}\" decoding=\"async\">{% endfor %}\n    </div>\n    {% if product.images.size > 1 %}\n    <div class=\"lb-product-detail__gallery-thumbs\" role=\"tablist\" aria-label=\"Product images\">\n      {% for image in product.images %}<button type=\"button\" class=\"lb-product-detail__gallery-thumb\" data-lb-gallery-thumb data-index=\"{{ forloop.index0 }}\" role=\"tab\" aria-selected=\"{% if forloop.first %}true{% else %}false{% endif %}\" tabindex=\"{% if forloop.first %}0{% else %}-1{% endif %}\" aria-label=\"Image {{ forloop.index }} of {{ product.images.size }}\"><img src=\"{{ image | image_url }}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\" decoding=\"async\"></button>{% endfor %}\n    </div>\n    {% endif %}\n  </lb-product-gallery>\n  {% endif %}\n  <div class=\"lb-product-detail__info\">\n  <h1>{{ product.title }}</h1>\n  {% if product.review_count > 0 %}<p class=\"lb-product-detail__rating\" aria-label=\"Rated {{ product.rating }} out of 5\">★ {{ product.rating }} <span class=\"lb-product-detail__rating-count\">({{ product.review_count }})</span></p>{% endif %}\n  <div class=\"lb-product-detail__price\">\n    <span class=\"lb-product-detail__price-current\">{{ product.price | times: 100 | money_with_currency: product.currency }}</span>\n    {% if product.compare_at_price and product.compare_at_price > product.price %}\n    <s class=\"lb-product-detail__price-compare\">{{ product.compare_at_price | times: 100 | money_with_currency: product.currency }}</s>\n    <span class=\"lb-product-detail__price-save\">Save {{ product.compare_at_price | minus: product.price | times: 100.0 | divided_by: product.compare_at_price | round }}%</span>\n    {% endif %}\n  </div>\n  {% if section.settings.showFurnitureFacts %}<div class=\"hab-quick-facts\" aria-label=\"Common product dimensions\"><p class=\"hab-support\"><strong>Common product dimensions</strong> · check the selected finish below.</p>{% if product.furniture_display.assembled != blank %}<p><strong>{{ product.furniture_display.assembled }}</strong><br><span class=\"hab-support\">Assembled dimensions</span></p>{% elsif product.furniture.assembled != blank %}<p><strong>{% if product.furniture.assembled.diameter %}{{ product.furniture.assembled.diameter }} Ø{% else %}{{ product.furniture.assembled.width | default: '—' }} W × {{ product.furniture.assembled.depth | default: '—' }} D{% endif %}{% if product.furniture.assembled.height %} × {{ product.furniture.assembled.height }} H{% endif %} {{ product.furniture.assembled.unit }}</strong><br><span class=\"hab-support\">Assembled dimensions</span></p>{% else %}<p>Assembled dimensions not supplied.</p>{% endif %}{% if product.furniture_display.seat_height != blank %}<p>Seat height: <span>{{ product.furniture_display.seat_height }}</span></p>{% elsif product.furniture.seat_height != blank %}<p>Seat height: {{ product.furniture.seat_height.value }} {{ product.furniture.seat_height.unit }}</p>{% endif %}<a class=\"hab-link\" href=\"#habitat-dimensions-{{ section.id }}\">Dimensions, material &amp; access ↓</a></div>{% endif %}\n  {% if product.options.size > 0 %}<lb-variant-picker data-lb-island=\"variant-picker\" data-product-id=\"{{ product.id }}\" data-variants=\"{{ product.variants | json }}\" class=\"lb-product-detail__variants\">{% for option in product.options %}<div class=\"lb-product-detail__variant-group\"><span class=\"lb-variant-option__name\">{{ option.name }}</span><div class=\"lb-product-detail__variant-values\">{% for value in option.values %}<button type=\"button\" data-lb-variant-option data-variant-name=\"{{ option.name }}\" data-variant-value=\"{{ value }}\" aria-pressed=\"false\">{{ value }}</button>{% endfor %}</div></div>{% endfor %}<p class=\"lb-product-detail__variant-status\" data-lb-variant-status role=\"status\"></p></lb-variant-picker>{% endif %}\n  {% if section.settings.showFurnitureFacts %}<section class=\"hab-current-facts\" data-lb-variant-facts data-lb-facts-namespace=\"furniture\" data-product-id=\"{{ product.id }}\" data-lb-variant-facts-state=\"common\" aria-labelledby=\"habitat-current-facts-{{ section.id }}\"><p class=\"hab-current-facts__status\" id=\"habitat-current-facts-{{ section.id }}\" data-lb-variant-facts-status role=\"status\" aria-live=\"polite\">Common product facts{% if product.options.size > 0 %} · select all finish options{% endif %}</p><dl><div><dt>Assembled</dt><dd data-lb-furniture-field=\"assembled\" data-lb-facts-missing=\"Assembled dimensions not supplied.\">{{ product.furniture_display.assembled | default: 'Assembled dimensions not supplied.' }}</dd></div><div><dt>Package</dt><dd data-lb-furniture-field=\"package\" data-lb-facts-missing=\"Package dimensions not supplied.\">{{ product.furniture_display.package | default: 'Package dimensions not supplied.' }}</dd></div><div><dt>Weight</dt><dd data-lb-furniture-field=\"weight\" data-lb-facts-missing=\"Weight not supplied.\">{{ product.furniture_display.weight | default: 'Weight not supplied.' }}</dd></div><div><dt>Seat height</dt><dd data-lb-furniture-field=\"seat_height\" data-lb-facts-missing=\"Seat height not supplied.\">{{ product.furniture_display.seat_height | default: 'Seat height not supplied.' }}</dd></div><div><dt>Materials</dt><dd data-lb-furniture-field=\"materials\" data-lb-facts-missing=\"Material information not supplied.\">{{ product.furniture_display.materials | default: 'Material information not supplied.' }}</dd></div><div><dt>Assembly</dt><dd data-lb-furniture-field=\"assembly\" data-lb-facts-missing=\"Assembly information not supplied.\">{{ product.furniture_display.assembly | default: 'Assembly information not supplied.' }}</dd></div><div><dt>Care</dt><dd data-lb-furniture-field=\"care\" data-lb-facts-missing=\"Care information not supplied.\">{{ product.furniture_display.care | default: 'Care information not supplied.' }}</dd></div></dl><p class=\"hab-support\">Only supplied measurements are listed. An absent width, depth, height or diameter is not supplied. Assembled and package measurements describe different things.</p><a class=\"hab-link\" href=\"#habitat-dimensions-{{ section.id }}\">Common reference, named finishes &amp; access guidance ↓</a></section>{% endif %}\n  <div class=\"lb-product-detail__purchase\">\n    <lb-add-to-cart data-lb-island=\"add-to-cart\" data-product-id=\"{{ product.id }}\" data-product-name=\"{{ product.title }}\" data-product-price=\"{{ product.price }}\" data-product-currency=\"{{ product.currency }}\" data-product-url=\"{{ product.url }}\">\n      <label class=\"lb-sr-only\" for=\"lb-quantity-{{ section.id }}\">Quantity</label>\n      <input type=\"number\" name=\"quantity\" id=\"lb-quantity-{{ section.id }}\" class=\"lb-product-detail__quantity\" value=\"1\" min=\"1\" inputmode=\"numeric\">\n      <button type=\"button\" class=\"lb-product-detail__cta lb-product-detail__cta--primary\" data-lb-add-to-cart{% if product.available == false %} disabled{% endif %}>{% if product.available == false %}Sold out{% else %}Add to cart{% endif %}</button>\n      {% if section.settings.showBuyNow %}<button type=\"button\" class=\"lb-product-detail__cta lb-product-detail__cta--secondary\" data-lb-buy-now{% if product.available == false %} disabled{% endif %}>Buy now</button>{% endif %}\n      <span data-lb-add-to-cart-status aria-live=\"polite\"></span>\n    </lb-add-to-cart>\n    <lb-wishlist-toggle data-lb-island=\"wishlist-toggle\" data-product-id=\"{{ product.id }}\" data-store-id=\"{{ shop.id }}\" data-in-wishlist=\"{% if product.in_wishlist %}true{% endif %}\"{% if buyer_wishlist.authenticated %} data-authenticated=\"true\" data-account-type=\"buyer\" data-buyer-id=\"{{ buyer_wishlist.buyerId }}\" data-buyer-linked=\"{% if buyer_wishlist.linked %}true{% endif %}\" data-buyer-unavailable=\"{% if buyer_wishlist.unavailable or buyer_wishlist.storeAccountUnavailable %}true{% endif %}\"{% elsif customer %} data-authenticated=\"true\" data-account-type=\"store_customer\"{% endif %} data-base-path=\"/store/{{ shop.subdomain }}\" aria-label=\"Add {{ product.title }} to wishlist\"></lb-wishlist-toggle>\n  </div>\n  {% if section.settings.showDescription and product.description %}\n  <details class=\"lb-product-detail__accordion\"><summary>Description</summary><div class=\"lb-product-detail__accordion-body\">{{ product.description }}</div></details>\n  {% endif %}\n  {% if shop.policies contains 'shipping' %}\n  <details class=\"lb-product-detail__accordion\"><summary>Shipping</summary><div class=\"lb-product-detail__accordion-body\"><a href=\"{{ routes.root_url }}/shipping\">Read our shipping policy</a></div></details>\n  {% endif %}\n  {% if shop.policies contains 'refund' or shop.policies contains 'returns' %}\n  <details class=\"lb-product-detail__accordion\"><summary>Returns</summary><div class=\"lb-product-detail__accordion-body\"><a href=\"{{ routes.root_url }}/returns\">Read our returns policy</a></div></details>\n  {% endif %}\n  </div>\n  </div>\n  {% if section.settings.showFurnitureFacts %}<section class=\"hab-facts\" id=\"habitat-dimensions-{{ section.id }}\" aria-label=\"Furniture measurements and materials\"><span class=\"hab-eyebrow\">Make space for it</span><h2>{{ section.settings.factsHeading }}</h2><p>Measure the room it will live in, then the access path it will take to get there.</p><p class=\"hab-support\">Product facts below are common reference information. A selected finish may override them; use its current facts above.</p><div class=\"hab-facts-layout\"><div>{% if section.settings.showDimensionDiagram and product.furniture.assembled != blank %}<div class=\"hab-dimension-box\" aria-label=\"Common product footprint schematic\"><p>{% if product.furniture.assembled.diameter %}Diameter: {{ product.furniture.assembled.diameter }} {{ product.furniture.assembled.unit }}{% elsif product.furniture.assembled.width %}Width: {{ product.furniture.assembled.width }} {{ product.furniture.assembled.unit }}{% endif %}</p><div class=\"hab-footprint{% if product.furniture.assembled.diameter %} hab-footprint-round{% endif %}\"><span>Footprint</span></div>{% if product.furniture.assembled.depth %}<p>Depth: {{ product.furniture.assembled.depth }} {{ product.furniture.assembled.unit }}</p>{% endif %}</div><p class=\"hab-support\">Common product footprint only. Schematic, not to scale. Check the current finish measurements; no access or fit is guaranteed.</p>{% endif %}<table><caption>Product facts (common) · selected finish facts are shown above</caption><tbody>{% if product.furniture_display.assembled != blank %}<tr><th scope=\"row\">Assembled dimensions</th><td>{{ product.furniture_display.assembled }}</td></tr>{% elsif product.furniture.assembled != blank %}{% assign dimension_keys = 'width,depth,height,diameter' | split: ',' %}{% for key in dimension_keys %}{% assign supplied = product.furniture.assembled[key] %}{% if supplied != nil %}<tr><th scope=\"row\">Assembled {{ key }}</th><td>{{ supplied }} {{ product.furniture.assembled.unit }}</td></tr>{% endif %}{% endfor %}{% else %}<tr><th scope=\"row\">Assembled size</th><td>Not supplied</td></tr>{% endif %}{% if product.furniture_display.seat_height != blank %}<tr><th scope=\"row\">Seat height</th><td>{{ product.furniture_display.seat_height }}</td></tr>{% elsif product.furniture.seat_height != blank %}<tr><th scope=\"row\">Seat height</th><td>{{ product.furniture.seat_height.value }} {{ product.furniture.seat_height.unit }}</td></tr>{% endif %}{% if product.furniture_display.package != blank %}<tr><th scope=\"row\">Package W × D × H</th><td>{{ product.furniture_display.package }}</td></tr>{% elsif product.furniture.package != blank %}<tr><th scope=\"row\">Package W × D × H</th><td>{{ product.furniture.package.width | default: '—' }} × {{ product.furniture.package.depth | default: '—' }} × {{ product.furniture.package.height | default: '—' }} {{ product.furniture.package.unit }}</td></tr>{% endif %}{% if product.furniture_display.weight != blank %}<tr><th scope=\"row\">Product weight</th><td>{{ product.furniture_display.weight }}</td></tr>{% elsif product.furniture.weight != blank %}<tr><th scope=\"row\">Product weight</th><td>{{ product.furniture.weight.value }} {{ product.furniture.weight.unit }}</td></tr>{% endif %}</tbody></table><p class=\"hab-note\">Package size is not assembled size. Compare supplied package dimensions with doors, stairs, turns and lifts.</p></div><div><h3>Product material &amp; assembly (common)</h3>{% if product.furniture.materials.size > 0 %}<p>{% for material in product.furniture.materials %}{{ material }}{% unless forloop.last %} · {% endunless %}{% endfor %}</p>{% else %}<p>Material information not supplied.</p>{% endif %}{% if product.furniture.assembly.status == 'assembled' %}<p>Arrives assembled.</p>{% elsif product.furniture.assembly.status == 'required' %}<p>Assembly required.</p>{% else %}<p>Assembly information not supplied.</p>{% endif %}{% if product.furniture.assembly.instructions != blank %}<p>{{ product.furniture.assembly.instructions }}</p>{% endif %}{% if product.furniture.assembly.tools != blank %}<p>Tools: {{ product.furniture.assembly.tools }}</p>{% endif %}{% if product.furniture.care != blank %}<details open><summary>Product care (common)</summary><p>{{ product.furniture.care }}</p></details>{% endif %}<details open><summary>Delivery &amp; access</summary><p>Delivery options and charges are confirmed by checkout for your address. A delivery date is not available unless a service result supplies one.</p>{% if shop.policies contains 'shipping' %}<a class=\"hab-link\" href=\"{{ routes.root_url }}/shipping\">Read the merchant’s shipping policy</a>{% endif %}</details></div></div>{% if product.variants.size > 0 %}<h3>Facts by named finish</h3><p class=\"hab-support\">Compare supplied facts for each actual option. Each list includes resolved product facts unless that finish overrides them. Choose every option above to see the current finish.</p><div class=\"hab-finish-facts\" data-lb-variant-facts-fallback data-product-id=\"{{ product.id }}\">{% for variant in product.variants limit: 100 %}{% assign facts = variant.furniture %}{% assign display = variant.furniture_display %}<div data-lb-variant-facts-row data-variant-id=\"{{ variant.id }}\"><h4>{{ facts.finish | default: variant.title | default: variant.name }}</h4><dl><div><dt>Assembled</dt><dd>{{ display.assembled | default: 'Assembled dimensions not supplied.' }}</dd></div><div><dt>Package</dt><dd>{{ display.package | default: 'Package dimensions not supplied.' }}</dd></div><div><dt>Weight</dt><dd>{{ display.weight | default: 'Weight not supplied.' }}</dd></div><div><dt>Seat height</dt><dd>{{ display.seat_height | default: 'Seat height not supplied.' }}</dd></div><div><dt>Materials</dt><dd>{{ display.materials | default: 'Material information not supplied.' }}</dd></div><div><dt>Assembly</dt><dd>{{ display.assembly | default: 'Assembly information not supplied.' }}</dd></div><div><dt>Care</dt><dd>{{ display.care | default: 'Care information not supplied.' }}</dd></div></dl></div>{% endfor %}</div>{% endif %}</section>{% endif %}\n  {% if section.settings.showReviews and product.reviews.size > 0 %}<div class=\"lb-product-reviews\" data-section-id=\"{{ section.id }}-reviews\">\n    <h2 class=\"lb-product-reviews__title\">Customer reviews ({{ product.review_count }})</h2>\n    {% for review in product.reviews %}<article class=\"lb-product-review\">\n      <header class=\"lb-product-review__head\"><strong class=\"lb-product-review__author\">{{ review.author }}</strong><span class=\"lb-product-review__stars\" aria-label=\"Rated {{ review.rating }} out of 5\">★ {{ review.rating }}</span>{% if review.is_verified %}<span class=\"lb-product-review__verified\">Verified purchase</span>{% endif %}</header>\n      {% if review.title %}<h3 class=\"lb-product-review__heading\">{{ review.title }}</h3>{% endif %}\n      {% if review.body %}<p class=\"lb-product-review__body\">{{ review.body }}</p>{% endif %}\n      {% if review.helpful_count > 0 %}<footer class=\"lb-product-review__helpful\">{{ review.helpful_count }} found this helpful</footer>{% endif %}\n    </article>{% endfor %}\n  </div>{% endif %}\n  {% if section.settings.showReviews %}<lb-review-form data-lb-island=\"review-form\" data-product-id=\"{{ product.id }}\" data-store-id=\"{{ shop.id }}\"></lb-review-form>{% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Product Detail\",\"tag\":\"section\",\"settings\":[{\"type\":\"toggle\",\"label\":\"Show gallery\",\"default\":true,\"id\":\"showGallery\"},{\"type\":\"toggle\",\"label\":\"Show description\",\"default\":true,\"id\":\"showDescription\"},{\"type\":\"toggle\",\"label\":\"Show reviews\",\"default\":true,\"id\":\"showReviews\"},{\"id\":\"showBuyNow\",\"type\":\"toggle\",\"label\":\"Show buy now\",\"default\":false},{\"id\":\"showFurnitureFacts\",\"type\":\"toggle\",\"label\":\"Show furniture facts\",\"default\":true},{\"id\":\"showDimensionDiagram\",\"type\":\"toggle\",\"label\":\"Show supplied footprint schematic\",\"default\":true},{\"id\":\"showRoomContext\",\"type\":\"toggle\",\"label\":\"Use the selected product image position as room context\",\"default\":false},{\"id\":\"factsHeading\",\"type\":\"text\",\"label\":\"Facts heading\",\"default\":\"Know every dimension.\"},{\"id\":\"contextMediaIndex\",\"type\":\"range\",\"label\":\"Room context image position (if supplied)\",\"min\":1,\"max\":20,\"step\":1,\"default\":2}],\"blocks\":[],\"presets\":[{\"name\":\"Product Detail\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"product-grid":{"path":"sections/product-grid.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Furniture object grid","presets":[{"blocks":[],"name":"Furniture object grid","settings":{}}],"settings":[{"default":"Objects with a purpose","id":"title","label":"Heading","type":"text"},{"default":"","id":"subtitle","label":"Description","type":"text"},{"id":"collectionId","label":"Collection","type":"collection"},{"default":4,"id":"productLimit","label":"Products to show","max":24,"min":1,"step":1,"type":"range"}],"tag":"section"},"source":"<section class=\"hab-theme\" data-section-id=\"{{ section.id }}\"><div class=\"hab-wrap hab-section\">{% if section.settings.title != blank or section.settings.subtitle != blank %}<div class=\"hab-heading\"><div>{% if section.settings.title != blank %}<h2>{{ section.settings.title }}</h2>{% endif %}{% if section.settings.subtitle != blank %}<p>{{ section.settings.subtitle }}</p>{% endif %}</div></div>{% endif %}{% assign furniture_products = section.products | default: collection.products %}{% if furniture_products.size > 0 %}<div class=\"hab-grid\">{% for item in furniture_products limit: section.settings.productLimit %}<article class=\"hab-card\"><a class=\"hab-card-image\" href=\"{{ item.url }}\">{% if item.featured_image != blank %}<img src=\"{{ item.featured_image | image_url }}\" alt=\"{{ item.title }}\" loading=\"lazy\" decoding=\"async\">{% else %}<span class=\"hab-placeholder\">Product photograph not supplied</span>{% endif %}{% if item.available == false %}<span class=\"hab-unavailable\">Unavailable</span>{% endif %}</a><div class=\"hab-card-heading\"><h3><a href=\"{{ item.url }}\">{{ item.title }}</a></h3><span class=\"hab-price\">{{ item.price | times: 100 | money_with_currency: item.currency }}</span></div>{% if item.furniture_display.assembled != blank %}<p class=\"hab-card-facts\">{{ item.furniture_display.assembled }}</p>{% elsif item.furniture.assembled != blank %}<p class=\"hab-card-facts\">{% if item.furniture.assembled.diameter %}{{ item.furniture.assembled.diameter }} Ø{% else %}{{ item.furniture.assembled.width | default: '—' }} W × {{ item.furniture.assembled.depth | default: '—' }} D{% endif %}{% if item.furniture.assembled.height %} × {{ item.furniture.assembled.height }} H{% endif %} {{ item.furniture.assembled.unit }}</p>{% else %}<p class=\"hab-card-facts\">Dimensions not supplied</p>{% endif %}{% if item.furniture.finish != blank %}<p class=\"hab-card-facts\">{{ item.furniture.finish }}</p>{% else %}{% for option in item.option_summaries %}<p class=\"hab-card-facts\">{{ option.name }}: {{ option.summary }}</p>{% endfor %}{% endif %}<a class=\"hab-link\" href=\"{{ item.url }}\">View dimensions &amp; options <span aria-hidden=\"true\">→</span></a></article>{% endfor %}</div><nav class=\"hab-pagination\" aria-label=\"Product pages\">{% if collection.pagination.previous_url != blank %}<a class=\"hab-link\" href=\"{{ collection.pagination.previous_url }}\">← Previous</a>{% endif %}{% if collection.pagination.page %}<span>Page {{ collection.pagination.page }}</span>{% endif %}{% if collection.pagination.next_url != blank %}<a class=\"hab-link\" href=\"{{ collection.pagination.next_url }}\">Next →</a>{% endif %}</nav>{% else %}<p>No pieces found. Try a broader collection or clear the filters.</p><a class=\"hab-link\" href=\"{{ routes.all_products_collection_url }}\">Explore all furniture</a>{% endif %}</div></section>\n{% schema %}\n{\"name\":\"Furniture object grid\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Objects with a purpose\",\"id\":\"title\"},{\"type\":\"text\",\"label\":\"Description\",\"default\":\"\",\"id\":\"subtitle\"},{\"type\":\"collection\",\"label\":\"Collection\",\"id\":\"collectionId\"},{\"type\":\"range\",\"label\":\"Products to show\",\"default\":4,\"min\":1,\"max\":24,\"step\":1,\"id\":\"productLimit\"}],\"blocks\":[],\"presets\":[{\"name\":\"Furniture object grid\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"rich-content":{"path":"sections/rich-content.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Rich Content","presets":[{"blocks":[],"name":"Rich Content","settings":{}}],"settings":[{"id":"title","label":"Title","type":"text"},{"id":"body","label":"Body","type":"richtext"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-rich-content\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.title }}</h1>\n  <div>{{ section.settings.body }}</div>\n</section>\n</div>\n{% schema %}\n{\"name\":\"Rich Content\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Title\",\"id\":\"title\"},{\"type\":\"richtext\",\"label\":\"Body\",\"id\":\"body\"}],\"blocks\":[],\"presets\":[{\"name\":\"Rich Content\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"search-box":{"path":"sections/search-box.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Search","presets":[{"blocks":[],"name":"Search","settings":{}}],"settings":[{"default":"Search products","id":"placeholder","label":"Placeholder","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-search\" data-section-id=\"{{ section.id }}\">\n  <lb-search data-lb-island=\"search\" data-search-url=\"{{ routes.search_url }}\">\n    <form role=\"search\" method=\"get\" action=\"{{ routes.search_url }}\" data-lb-search-form>\n      <label class=\"lb-sr-only\" for=\"lb-search-input-{{ section.id }}\">Search products</label>\n      <input type=\"search\" name=\"search\" id=\"lb-search-input-{{ section.id }}\" data-lb-search-input placeholder=\"{{ section.settings.placeholder }}\" aria-label=\"Search products\" value=\"{{ search.terms }}\">\n      <button type=\"submit\" aria-label=\"Search\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"11\" cy=\"11\" r=\"8\"></circle><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line></svg><span class=\"lb-sr-only\">Search</span></button>\n    </form>\n  </lb-search>\n  {% if search.terms %}<p class=\"lb-search__terms\">Results for \"{{ search.terms }}\"</p>{% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Search\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Placeholder\",\"default\":\"Search products\",\"id\":\"placeholder\"}],\"blocks\":[],\"presets\":[{\"name\":\"Search\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"services-grid":{"path":"sections/services-grid.liquid","schema":{"blocks":[{"name":"Service","settings":[{"id":"title","label":"Title","type":"text"},{"id":"description","label":"Description","type":"textarea"},{"id":"link","label":"Link","type":"url"}],"type":"service"}],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Services Grid","presets":[{"blocks":[],"name":"Services Grid","settings":{}}],"settings":[{"default":"Services","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-services-grid\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% for block in section.blocks %}<article {{ block.editor_attributes | raw }}><h3>{{ block.settings.title }}</h3><p>{{ block.settings.description }}</p><a href=\"{{ block.settings.link | store_url }}\">Learn more</a>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</article>{% endfor %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Services Grid\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Title\",\"default\":\"Services\",\"id\":\"title\"}],\"blocks\":[{\"type\":\"service\",\"name\":\"Service\",\"settings\":[{\"type\":\"text\",\"label\":\"Title\",\"id\":\"title\"},{\"type\":\"textarea\",\"label\":\"Description\",\"id\":\"description\"},{\"type\":\"url\",\"label\":\"Link\",\"id\":\"link\"}]}],\"presets\":[{\"name\":\"Services Grid\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"skills-section":{"path":"sections/skills-section.liquid","schema":{"blocks":[{"name":"Skill","settings":[{"id":"name","label":"Skill","type":"text"},{"id":"level","label":"Level","max":100,"min":0,"step":5,"type":"range"}],"type":"skill"}],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Skills Section","presets":[{"blocks":[],"name":"Skills Section","settings":{}}],"settings":[{"default":"Skills","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-skills-section\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% if section.blocks.size > 0 %}<h3>General</h3>{% endif %}\n  {% for block in section.blocks %}<span {{ block.editor_attributes | raw }} data-level=\"{{ block.settings.level }}\">{{ block.settings.name }} {{ block.settings.level }}%{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</span>{% endfor %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Skills Section\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Title\",\"default\":\"Skills\",\"id\":\"title\"}],\"blocks\":[{\"type\":\"skill\",\"name\":\"Skill\",\"settings\":[{\"type\":\"text\",\"label\":\"Skill\",\"id\":\"name\"},{\"type\":\"range\",\"label\":\"Level\",\"min\":0,\"max\":100,\"step\":5,\"id\":\"level\"}]}],\"presets\":[{\"name\":\"Skills Section\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"spotlight":{"path":"sections/spotlight.liquid","schema":{"blocks":[{"name":"Badge","settings":[],"type":"badge"},{"name":"App block","settings":[],"type":"@app"}],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Spotlight","presets":[{"blocks":[],"name":"Spotlight","settings":{}}],"settings":[{"default":"Made for daily buyers","id":"heading","label":"Heading","type":"text"},{"id":"subheading","label":"Subheading","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-first-party-spotlight\" data-section-id=\"{{ section.id }}\">\n  <p>{{ section.settings.subheading }}</p>\n  <h2>{{ section.settings.heading }}</h2>\n  <div class=\"lb-first-party-spotlight__blocks\">\n    {% for block in section.blocks %}\n      {{ block.content | raw }}\n    {% endfor %}\n  </div>\n</section>\n</div>\n{% schema %}\n{\"name\":\"Spotlight\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"Made for daily buyers\",\"id\":\"heading\"},{\"type\":\"text\",\"label\":\"Subheading\",\"id\":\"subheading\"}],\"blocks\":[{\"type\":\"badge\",\"name\":\"Badge\",\"settings\":[]},{\"type\":\"@app\",\"name\":\"App block\",\"settings\":[]}],\"presets\":[{\"name\":\"Spotlight\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"testimonials":{"path":"sections/testimonials.liquid","schema":{"blocks":[{"name":"Testimonial","settings":[{"id":"quote","label":"Quote","type":"textarea"},{"id":"author","label":"Author","type":"text"}],"type":"testimonial"}],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Testimonials","presets":[{"blocks":[],"name":"Testimonials","settings":{}}],"settings":[{"default":"What customers say","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-testimonials\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% if section.blocks.size > 0 %}<div class=\"lb-testimonials__items\">{% for block in section.blocks %}<blockquote {{ block.editor_attributes | raw }}><p>{{ block.settings.quote }}</p><cite>{{ block.settings.author }}</cite>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</blockquote>{% endfor %}</div>\n  {% else %}<p class=\"lb-testimonials__empty\">Add customer reviews to build trust.</p>{% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Testimonials\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Title\",\"default\":\"What customers say\",\"id\":\"title\"}],\"blocks\":[{\"type\":\"testimonial\",\"name\":\"Testimonial\",\"settings\":[{\"type\":\"textarea\",\"label\":\"Quote\",\"id\":\"quote\"},{\"type\":\"text\",\"label\":\"Author\",\"id\":\"author\"}]}],\"presets\":[{\"name\":\"Testimonials\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"trust-badges":{"path":"sections/trust-badges.liquid","schema":{"blocks":[{"name":"Badge","settings":[{"default":"New","id":"label","label":"Label","type":"text"}],"type":"badge"}],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Supplied service information","presets":[{"blocks":[],"name":"Supplied service information","settings":{}}],"settings":[{"default":"","id":"dimensionsText","label":"Measurement information","type":"text"},{"default":"","id":"assemblyText","label":"Assembly information","type":"text"},{"default":"","id":"deliveryText","label":"Actual delivery information","type":"text"}],"tag":"section"},"source":"<section class=\"hab-theme\" data-section-id=\"{{ section.id }}\"><div class=\"hab-wrap hab-services\">{% if section.settings.dimensionsText != blank %}<div><h3>Dimensions, in the open</h3><p>{{ section.settings.dimensionsText }}</p></div>{% endif %}{% if section.settings.assemblyText != blank %}<div><h3>Assembly, explained</h3><p>{{ section.settings.assemblyText }}</p></div>{% endif %}{% if section.settings.deliveryText != blank %}<div><h3>Delivery, with context</h3><p>{{ section.settings.deliveryText }}</p></div>{% endif %}</div>{% for block in section.blocks %}{{ block.content | raw }}{% endfor %}</section>\n{% schema %}\n{\"name\":\"Supplied service information\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Measurement information\",\"default\":\"\",\"id\":\"dimensionsText\"},{\"type\":\"text\",\"label\":\"Assembly information\",\"default\":\"\",\"id\":\"assemblyText\"},{\"type\":\"text\",\"label\":\"Actual delivery information\",\"default\":\"\",\"id\":\"deliveryText\"}],\"blocks\":[{\"type\":\"badge\",\"name\":\"Badge\",\"settings\":[{\"type\":\"text\",\"label\":\"Label\",\"default\":\"New\",\"id\":\"label\"}]}],\"presets\":[{\"name\":\"Supplied service information\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"},"video-hero":{"path":"sections/video-hero.liquid","schema":{"blocks":[],"disabled_on":{"templates":[]},"enabled_on":{"templates":["*"]},"name":"Video Hero","presets":[{"blocks":[],"name":"Video Hero","settings":{}}],"settings":[{"default":"See the fit in motion","id":"heading","label":"Heading","type":"text"},{"default":"A quick look at how each drop moves, from the box to your feet.","id":"subheading","label":"Subheading","type":"textarea"},{"id":"videoUrl","info":"A YouTube or Vimeo embed URL (for example https://www.youtube.com/embed/VIDEO_ID). Leave blank to hide the video.","label":"Video embed URL","type":"url"}],"tag":"section"},"source":"<div class=\"hab-theme\"><section class=\"lb-video-hero\" data-section-id=\"{{ section.id }}\">\n  <div class=\"lb-video-hero__copy\">\n    <h2 class=\"lb-video-hero__heading\">{{ section.settings.heading }}</h2>\n    {% if section.settings.subheading %}<p class=\"lb-video-hero__subheading\">{{ section.settings.subheading }}</p>{% endif %}\n  </div>\n  {% if section.settings.videoUrl != blank %}<div class=\"lb-video-hero__embed\"><iframe src=\"{{ section.settings.videoUrl | video_url }}\" title=\"{{ section.settings.heading }}\" loading=\"lazy\" sandbox=\"allow-scripts allow-same-origin allow-presentation\" allowfullscreen></iframe></div>{% endif %}\n</section>\n</div>\n{% schema %}\n{\"name\":\"Video Hero\",\"tag\":\"section\",\"settings\":[{\"type\":\"text\",\"label\":\"Heading\",\"default\":\"See the fit in motion\",\"id\":\"heading\"},{\"type\":\"textarea\",\"label\":\"Subheading\",\"default\":\"A quick look at how each drop moves, from the box to your feet.\",\"id\":\"subheading\"},{\"type\":\"url\",\"label\":\"Video embed URL\",\"info\":\"A YouTube or Vimeo embed URL (for example https://www.youtube.com/embed/VIDEO_ID). Leave blank to hide the video.\",\"id\":\"videoUrl\"}],\"blocks\":[],\"presets\":[{\"name\":\"Video Hero\",\"settings\":{},\"blocks\":[]}],\"enabled_on\":{\"templates\":[\"*\"]},\"disabled_on\":{\"templates\":[]}}\n{% endschema %}"}},"templates":{"article":{"layout":"theme","name":"Article","order":["article-content-default"],"sections":{"article-content-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{},"type":"article-content"}}},"blog":{"layout":"theme","name":"Blog","order":["blog-listing-default"],"sections":{"blog-listing-default":{"block_order":[],"blocks":{},"disabled":false,"settings":