cks":{},"disabled":false,"settings":{},"type":"hero-banner"},"habitat-service-information":{"block_order":[],"blocks":{},"disabled":false,"settings":{},"type":"trust-badges"}}},"list-collections":{"layout":"theme","name":"All collections","order":["list-collections-grid"],"sections":{"list-collections-grid":{"block_order":[],"blocks":{},"disabled":false,"settings":{"subtitle":"Browse every collection in the store.","title":"All collections"},"type":"category-grid"}}},"not_found":{"layout":"theme","name":"404 Not Found","order":["404-page-default"],"sections":{"404-page-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{},"type":"404-page"}}},"page":{"layout":"theme","name":"Page","order":["page-content-default"],"sections":{"page-content-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{},"type":"page-content"}}},"password":{"layout":"theme","name":"Password","order":["password-gate-default"],"sections":{"password-gate-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{"heading":"Coming Soon"},"type":"password-gate"}}},"policy":{"layout":"theme","name":"Policy page","order":["policy-content-default"],"sections":{"policy-content-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{},"type":"policy-content"}}},"product":{"layout":"theme","name":"Habitat spatial product","order":["habitat-product-selection","habitat-related-objects"],"sections":{"habitat-product-selection":{"block_order":[],"blocks":{},"disabled":false,"settings":{"contextMediaIndex":2,"factsHeading":"Know every dimension.","showBuyNow":false,"showDescription":true,"showDimensionDiagram":true,"showFurnitureFacts":true,"showGallery":true,"showReviews":true,"showRoomContext":false},"type":"product-detail"},"habitat-related-objects":{"block_order":[],"blocks":{},"disabled":false,"settings":{"productLimit":2,"requireSelection":true,"title":"A place for the small things."},"type":"featured-products"}}},"search":{"layout":"theme","name":"LetB