m","liquid.section.cta-section","liquid.section.featured-products","liquid.section.experience-timeline","liquid.section.faq-accordion","liquid.section.footer","liquid.section.header","liquid.section.hero-banner","liquid.section.marquee","liquid.section.portfolio-grid","liquid.section.product-detail","liquid.section.product-grid","liquid.section.rich-content","liquid.section.services-grid","liquid.section.skills-section","liquid.section.testimonials","liquid.section.trust-badges","liquid.section.newsletter-signup","liquid.section.spotlight","liquid.section.video-hero","liquid.section.habitat-measurement-guide","liquid.block.badge","liquid.app-block"],"asset_manifest":{},"performance_budget":{},"renderer_manifest":{"assets":{},"engine":"liquid","liquid_ready":true,"renderer_version":"0.1.0"}},"schemaManifest":{"block_schemas":{"@app":{"fields":{"extension_handle":{"label":"Extension handle","maxLength":120,"type":"text"},"slot":{"label":"Slot","maxLength":160,"type":"text"}},"name":"App block"},"badge":{"fields":{"label":{"default":"New","label":"Label","type":"text"}},"name":"Badge","source_path":"blocks/badge.liquid"}},"layout_schema":{"theme":{"path":"layout/theme.liquid","source":"<!doctype html>\n<html lang=\"{{ request.locale | default: \"en\" }}\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  {% assign lb_page_title = shop.name %}\n  {% assign lb_meta_description = settings.metaDescription | default: shop.description | strip_html | truncate: 160 %}\n  <title>{{ lb_page_title }}</title>\n  {% if lb_meta_description != blank %}<meta name=\"description\" content=\"{{ lb_meta_description }}\">{% endif %}\n  <meta name=\"twitter:card\" content=\"{% if settings.socialImageUrl != blank %}summary_large_image{% else %}summary{% endif %}\">\n  <meta name=\"twitter:title\" content=\"{{ lb_page_title }}\">\n  {% if lb_meta_description != blank %}<meta name=\"twitter:description\" content=\"{{ lb_meta_description }}\">{% endif %}\n  {% if settings.socialImageUrl != blank %}<meta name=\"twitter:image\" content=\"{{ settings.socialImageUrl | image_url }}\">{% endif %}\n  <style data-lb-layout=\"1\">\n    :root{--lb-focus-ring-width:2px;--lb-focus-ring-color:var(--accent,#2563eb);--lb-focus-offset:2px;--lb-space-sm:0.5rem;--lb-space-md:0.75rem;--lb-space-lg:1rem;--lb-radius-sm:0.375rem;--lb-layout-max:72rem;--lb-layout-gutter:1rem;--lb-layout-breakpoint:48em;}\n    .lb-theme :where(a,button,input,select,textarea,summary,details,[tabindex]):focus-visible{outline:var(--lb-focus-ring-width) solid var(--lb-focus-ring-color);outline-offset:var(--lb-focus-offset);}\n    .lb-skip-link{position:absolute;left:-9999px;top:0;z-index:100;padding:var(--lb-space-md) var(--lb-space-lg);border-radius:var(--lb-radius-sm);background:var(--surface,#f8fafc);color:var(--foreground,#1a1a2e);font-weight:600;}\n    .lb-skip-link:focus,.lb-skip-link:focus-visible{left:var(--lb-space-lg);top:var(--lb-space-lg);}\n    .lb-layout__header,.lb-layout__footer{display:flex;flex-direction:column;align-items:flex-start;gap:var(--lb-space-md);margin-inline:auto;max-width:min(var(--lb-layout-max),calc(100vw - var(--lb-layout-gutter) * 2));padding-block:var(--lb-space-lg);padding-inline:var(--lb-layout-gutter);}\n    .lb-layout__brand{font-family:var(--font-display,inherit);font-weight:700;}\n    .lb-layout__nav{display:flex;flex-wrap:wrap;gap:var(--lb-space-md);}\n    .lb-layout__legal{margin:0;font-size:0.875rem;}\n    @media (min-width:48em){.lb-layout__header,.lb-layout__footer{flex-direction:row;align-items:center;justify-content:space-between;}}\n  </style>\n  {{ content_for_header | raw }}\n<style data-niche-order-presentation=\"1\">.lb-order-facts{min-width:0;max-width:100%;margin-block:.75rem}.lb-order-facts>summary{min-height:44px;cursor:pointer;padding-block:.5rem}.lb-order-facts__text{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}.lb-order-facts__missing{font-size:.875em;overflow-wrap:anywhere}</style>\n<style data-habitat=\"2\">\n.hab-theme{--hab-muted:var(--hab-muted-color,#625c50);--hab-edge:var(--hab-boundary-color,#7b7261);--hab-soft:color-mix(in srgb,var(--hab-edge) 35%,var(--background));--hab-sand:var(--surface,#e9e2d5);--hab-label:var(--hab-action-label,#fff);--font-body:var(--font-main,'Source Sans Pro',Arial,sans-serif);--font-display:var(--font-heading,'Libre Baskerville',Georgia,serif);--footer-bg:var(--hab-sand);--footer-text:var(--foreground);--footer-text-muted:var(--hab-muted);background:var(--background);color:var(--foreground);font:1.0625rem/1.5 var(--font-body)}\n.hab-theme *{box-sizing:border-box}.hab-theme a{color:inherit}.hab-theme img{max-width:100%;display:block}.hab-theme :where(h1,h2,h3){font-family:var(--font-display);font-weight:400;line-height:1.23;letter-spacing:-.035em;overflow-wrap:anywhere}.hab-theme h1{font-size:clamp(2rem,4vw,3.5rem)}.hab-theme h2{font-size:clamp(1.75rem,3vw,2.2rem)}.hab-theme h3{font-size:1.5rem}.hab-theme p{color:var(--hab-muted)}.hab-theme :where(a,button,input,select,summary):focus-visible{outline:2px solid var(--hab-focus-color,#005fcc);outline-offset:4px}.hab-theme :where(input,select,button){font:inherit}.hab-wrap{width:min(1320px,calc(100% - 112px));margin-inline:auto}.hab-section{padding-block:72px}.hab-eyebrow{text-transform:uppercase;letter-spacing:.16em;font-size:.8125rem;font-weight:600}.hab-heading{display:flex;justify-content:space-between;align-items:end;gap:32px;margin-bottom:30px}.hab-heading h2{margin:12px 0}.hab-button{min-height:48px;padding:13px 23px;border:1px solid var(--primary);border-radius:var(--radius,6px);background:var(--primary);color:var(--hab-label)!important;font-weight:600;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:12px}.hab-theme .hab-link{color:var(--primary);display:inline-flex;align-items:center;min-height:44px;text-underline-offset:5px}.hab-support,.hab-count{font-size:.9375rem}.hab-placeholder{display:grid;place-items:center;padding:24px;text-align:center;min-height:240px;background:var(--hab-sand);color:var(--hab-muted)}\n.hab-theme .lb-announcement-bar{background:var(--primary);color:var(--hab-label);padding:9px 20px;text-align:center;font-size:.875rem}.hab-theme .lb-announcement-bar__inner{justify-content:center}.hab-theme .lb-header{background:var(--background);border-bottom:1px solid var(--hab-soft)}.hab-theme .lb-header__inner{width:min(1320px,calc(100% - 112px));padding-block:20px;margin:auto;flex-wrap:wrap}.hab-theme .lb-header__nav a,.hab-theme .lb-header__actions a,.hab-theme .lb-header__brand{text-decoration:none}.hab-theme .lb-header__brand{font-family:var(--font-display);font-weight:400;letter-spacing:.12em;text-transform:uppercase;font-size:1.8rem}.hab-theme .lb-header__nav-links{gap:25px}.hab-theme .lb-footer{background:var(--hab-sand);padding:45px max(28px,calc((100vw - 1320px)/2));border-top:1px solid var(--hab-soft)}\n.hab-hero-heading{display:grid;grid-template-columns:1fr 1fr;align-items:end;gap:50px;padding-block:45px 32px}.hab-hero-heading h1{margin:14px 0 0;max-width:640px}.hab-hero-heading p{max-width:400px;font-size:1.25rem;justify-self:end}.hab-room-story{display:grid;grid-template-columns:250px minmax(0,1fr);background:var(--hab-sand)}.hab-room-index{padding:28px;display:flex;flex-direction:column;gap:8px;justify-content:center}.hab-room-index a{min-height:60px;display:flex;align-items:center;justify-content:space-between;gap:12px;border-top:1px solid var(--hab-soft);text-decoration:none;color:var(--foreground);overflow-wrap:anywhere}.hab-room-media{min-width:0}.hab-room-media img{width:100%;height:510px;object-fit:cover}.hab-focus-top img{object-position:center top}.hab-focus-bottom img{object-position:center bottom}.hab-room-caption{padding:16px 24px;background:var(--background);display:flex;justify-content:space-between;gap:24px;align-items:center}.hab-guide-strip{display:flex;justify-content:space-between;gap:24px;align-items:center;padding-block:25px 35px;border-bottom:1px solid var(--hab-soft)}.hab-hero-empty .hab-room-story{grid-template-columns:1fr}.hab-hero-empty .hab-room-index{display:flex;flex-direction:row;flex-wrap:wrap;justify-content:start}.hab-hero-empty .hab-room-index>a{min-width:150px}.hab-hero-empty .hab-room-index>span{width:100%}\n.hab-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:32px}.hab-card{min-width:0}.hab-card-image{position:relative;display:block;aspect-ratio:4/3;background:var(--hab-sand);text-decoration:none}.hab-card-image img{width:100%;height:100%;object-fit:contain}.hab-card-image .hab-placeholder{height:100%;min-height:0}.hab-unavailable{position:absolute;bottom:12px;left:12px;background:var(--background);color:var(--foreground);padding:5px 10px;font-size:.875rem}.hab-card-heading{display:flex;justify-content:space-between;gap:18px;align-items:start;padding-top:18px}.hab-card-heading h3{margin:0;font-size:1.5rem}.hab-card-heading h3 a{text-decoration:none;color:var(--foreground)}.hab-price{white-space:nowrap;font-size:1.25rem;font-variant-numeric:tabular-nums}.hab-card-facts{font-size:1rem;margin:8px 0}.hab-pagination{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:20px;margin-block:30px}.hab-breadcrumb{display:flex;gap:12px;flex-wrap:wrap;font-size:.875rem;margin-bottom:28px}.hab-discovery h1{margin:12px 0 20px}.hab-category-rail{display:flex;gap:22px;flex-wrap:wrap;border-block:1px solid var(--hab-soft);margin-top:30px;padding-block:15px}.hab-filters{display:flex;align-items:end;gap:16px;flex-wrap:wrap;margin-block:24px}.hab-filters label{display:grid;gap:8px;font-size:.9375rem;min-width:0}.hab-filters input,.hab-filters select{min-height:46px;max-width:100%;padding:10px 12px;border:1px solid var(--hab-edge);border-radius:var(--radius,6px);background:var(--background);color:var(--foreground)}.hab-filters input[type=number]{width:150px}\n.hab-material{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}.hab-material img{width:100%;aspect-ratio:4/3;object-fit:contain;background:var(--hab-sand)}.hab-material h2{margin:12px 0 22px}.hab-material-empty{grid-template-columns:1fr}.hab-education{background:var(--hab-sand);padding:45px;display:grid;grid-template-columns:1fr 1fr;gap:55px}.hab-education h2{margin:12px 0 20px}.hab-steps{list-style:none;margin:0;padding:0}.hab-steps li{display:grid;grid-template-columns:35px 1fr;gap:18px;margin-block:18px}.hab-steps h3{font:600 1.0625rem var(--font-body);letter-spacing:0;margin:0 0 8px}.hab-services{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:32px;padding-block:35px;border-top:1px solid var(--hab-soft)}.hab-services h3{font:600 1.125rem var(--font-body);letter-spacing:0}.hab-services p{font-size:1rem}.hab-services:empty{display:none}\n.hab-theme .lb-product-detail{width:min(1320px,calc(100% - 112px));margin:auto;padding-block:28px 60px}.hab-theme .lb-product-detail__layout{display:grid;grid-template-columns:1.15fr 1fr;gap:65px}.hab-theme .lb-product-detail__gallery-image{width:100%;aspect-ratio:4/3;object-fit:contain;background:var(--hab-sand)}.hab-theme .lb-product-detail__gallery-main{background:var(--hab-sand)}.hab-theme .lb-product-detail__info{min-width:0}.hab-theme .lb-product-detail__info>h1{font-size:clamp(2rem,3vw,2.7rem)}.hab-theme .lb-product-detail__price-current{font-size:1.6rem}.hab-theme .lb-product-detail__variant-values{gap:12px;flex-wrap:wrap}.hab-theme .lb-product-detail__variant-values button{min-height:48px;padding:10px 16px;border:1px solid var(--hab-edge);border-radius:var(--radius,6px);background:var(--background);color:var(--foreground)}.hab-theme .lb-product-detail__variant-values button[aria-pressed=true]{background:var(--primary);color:var(--hab-label)}.hab-theme .lb-product-detail__variant-values button[disabled]{text-decoration:line-through}.hab-theme .lb-product-detail__cta{min-height:48px;border-radius:var(--radius,6px)}.hab-theme .lb-product-detail__cta--primary{b