ss=\"lb-layout__brand\" href=\"{{ routes.root_url }}\">{{ shop.name }}</a>\n    <nav class=\"lb-layout__nav\" aria-label=\"Primary\">\n      {% if linklists.main_menu.links.size > 0 %}{% for link in linklists.main_menu.links %}<a href=\"{{ link.url | store_url }}\"{% if link.active %} aria-current=\"page\"{% endif %}>{{ link.title }}</a>{% endfor %}\n      {% else %}<a href=\"{{ routes.all_products_collection_url }}\">Products</a><a href=\"{{ routes.search_url }}\">Search</a><a href=\"{{ routes.cart_url }}\">Cart</a><a href=\"{{ routes.account_url }}\">Account</a>{% endif %}\n    </nav>\n  </header>\n  <main id=\"MainContent\">\n    {{ content_for_layout | raw }}\n  </main>\n  <footer class=\"lb-layout__footer\">\n    {% if linklists.footer.links.size > 0 %}<nav class=\"lb-layout__nav\" aria-label=\"Footer\">{% for link in linklists.footer.links %}<a href=\"{{ link.url | store_url }}\">{{ link.title }}</a>{% endfor %}</nav>{% endif %}\n    <p class=\"lb-layout__legal\">&copy; {{ shop.name }}</p>\n  </footer>\n  {{ content_for_footer | raw }}\n</body>\n</html>"}},"liquidBundle":{"blocks":{"badge":{"path":"blocks/badge.liquid","schema":{"name":"Badge","presets":[],"settings":[{"default":"New","id":"label","label":"Label","type":"text"}]},"source":"<span {{ block.editor_attributes | raw }} class=\"lb-badge\">{{ block.settings.label }}{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</span>"}},"config":{"settings_data":{"current":{"accentColor":"#7B7261","backgroundColor":"#F7F3EB","bodyFontFamily":"Source Sans Pro","borderRadius":6,"faviconUrl":"","headingFontFamily":"Libre Baskerville","metaDescription":"","primaryColor":"#4E573E","secondaryColor":"#625C50","socialImageUrl":"","surfaceColor":"#E9E2D5","textColor":"#302C25"},"presets":{"Aura":{"accentColor":"#D4AF7A","backgroundColor":"#FFFFFF","bodyFontFamily":"Lato","borderRadius":16,"headingFontFamily":"Cormorant Garamond","primaryColor":"#C2798B","se