me .lb-product-detail__cta--primary{background:var(--primary);color:var(--mg-label)}.mg-theme .lb-product-detail__quantity{width:64px}.mg-theme .lb-product-detail__purchase lb-add-to-cart{display:flex;flex-wrap:wrap;gap:12px}.mg-theme [data-lb-add-to-cart-status]{flex-basis:100%}.mg-theme .lb-product-detail__accordion{border-color:var(--mg-border)}.mg-facts{border-top:1px solid var(--mg-border);margin-top:22px;padding-top:20px}.mg-facts h2{font-size:1.4rem}.mg-facts dl{margin:0}.mg-facts dl>div{display:grid;grid-template-columns:145px 1fr;gap:20px;border-bottom:1px solid var(--mg-border);padding:11px 0}.mg-facts dt{color:var(--mg-muted)}.mg-facts dd{margin:0;overflow-wrap:anywhere}.mg-editions{display:grid;gap:12px}.mg-edition{border:1px solid var(--mg-border);padding:16px}.mg-edition h3{font:600 1rem/1.5 var(--font-body,Arial,sans-serif);letter-spacing:0;margin:0 0 8px}.mg-reading{max-width:68ch;margin:56px auto;padding:32px 0;border-top:1px solid var(--mg-border)}.mg-reading h2{font-size:1.7rem}.mg-reading blockquote{font:1.12rem/1.9 var(--font-display,Georgia,serif);white-space:pre-line;margin:24px 0;overflow-wrap:anywhere}.mg-reading cite{font:inherit;color:var(--mg-muted)}\n.mg-theme :where(.lb-cart,.lb-customer-account,.lb-customer-orders,.lb-customer-order-detail,.lb-customer-settings,.lb-customer-addresses){width:min(1240px,calc(100% - 112px));margin-inline:auto}.mg-theme :where(.lb-cart__checkout,.lb-cart-drawer__checkout){background:var(--primary);color:var(--mg-label)}.mg-theme .lb-cart-item__image{object-fit:contain}.mg-theme :where(.lb-policy-content,.lb-page-content,.lb-article-content){max-width:70ch;margin-inline:auto;padding:40px 24px;overflow-wrap:anywhere}.mg-theme :where(.lb-cart,.lb-customer-account,.lb-customer-orders,.lb-customer-order-detail) :where(p,td,dd,strong,a){overflow-wrap:anywhere}\n@media(max-width:1000px){.mg-wrap{width:calc(100% - 64px)}.mg-opening{gap:35px}.mg-index-feature{grid-template-columns:190px 1fr;gap:24px}.mg-feature{gap