ze:.8rem}.my-empty-image{display:grid;place-items:center;height:100%;padding:2rem;text-align:center;color:var(--my-muted)}.my-collections{display:flex;flex-wrap:wrap;gap:.75rem}.my-collections a{border:1px solid var(--my-border);padding:.7rem 1.2rem;border-radius:3rem;background:var(--my-surface);min-height:2.75rem}.my-story{display:grid;grid-template-columns:1fr 1fr;gap:3rem;align-items:center}.my-story>img{width:100%;aspect-ratio:4/3;object-fit:contain;border-radius:var(--my-radius,.8rem)}.my-story-no-image{grid-template-columns:1fr;max-width:50rem}.my-filters{display:flex;flex-wrap:wrap;gap:1rem;align-items:end;margin-top:1.5rem}.my-filters label{flex:1;min-width:9rem}.my-filters input{width:100%}.my-pagination{display:flex;flex-wrap:wrap;gap:1.5rem;align-items:center;justify-content:center;margin-top:2rem}.my-empty{padding:2rem;border:1px solid var(--my-border);border-radius:var(--my-radius,.8rem);background:var(--my-surface)}\n.my-theme .lb-product-detail{width:min(76rem,calc(100% - 6rem));margin:auto;padding-block:2rem 3.5rem}.my-theme .lb-product-detail__layout{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:3rem;align-items:start}.my-theme .lb-product-detail__gallery{position:static}.my-theme .lb-product-detail__gallery-main{background:var(--my-surface);border:1px solid var(--my-border);border-radius:var(--my-radius,.8rem)}.my-theme .lb-product-detail__gallery-image{width:100%;height:100%;object-fit:contain;aspect-ratio:1}.my-theme .lb-product-detail__gallery-thumbs{display:flex;gap:.7rem;flex-wrap:wrap;margin-top:1rem}.my-theme .lb-product-detail__gallery-thumb{width:4.5rem;height:4.5rem;padding:.3rem;border:1px solid var(--my-border);background:var(--my-surface)}.my-theme .lb-product-detail__gallery-thumb img{width:100%;height:100%;object-fit:contain}.my-theme .lb-product-detail__info h1{font-size:clamp(1.8rem,2.7vw,2.6rem);margin-block:0 1rem}.my-theme .lb-product-detail__price{font-size:1.3rem;font-weight:600}.my-theme .lb-product-detail__breadcrumb{display:flex;flex-wrap:wrap;gap:.7rem;font-size:.85rem;margin-bottom:1.5rem}.my-theme .lb-product-detail__variants{display:block;margin-block:1rem}.my-theme .lb-product-detail__variant-values{display:flex;flex-wrap:wrap;gap:.6rem;margin-top:.5rem}.my-theme [data-lb-variant-option]{min-height:2.75rem;padding:.6rem .9rem;background:var(--my-surface);color:var(--my-ink);border:1px solid var(--my-border);border-radius:var(--my-radius,.4rem)}.my-theme [data-lb-variant-option][aria-pressed=\"true\"]{outline:1px solid var(--my-action);border-color:var(--my-action);background:var(--my-canvas)}.my-theme lb-add-to-cart{display:flex;flex-wrap:wrap;gap:1rem;align-items:center}.my-theme .lb-product-detail__quantity{width:5rem}.my-theme .lb-product-detail__accordion{padding-block:1rem;border-top:1px solid var(--my-border);margin-top:1rem}.my-theme .lb-product-detail__accordion summary{min-height:2.75rem;display:flex;align-items:center;cursor:pointer;font-weight:600}\n.my-config{flex-basis:100%;background:var(--my-surface);border:1px solid var(--my-border);border-radius:var(--my-radius,.8rem);padding:1.4rem}.my-config h2{font-size:1.2rem;margin:0 0 1rem}.my-config fieldset{margin:1rem 0;padding:0;border:0;display:grid;gap:1rem}.my-config legend{font-weight:600;margin-bottom:.5rem}.my-stages{list-style:none;padding:0;display:flex;gap:1rem;flex-wrap:wrap;font-size:.8rem;color:var(--my-muted)}.my-stages li[aria-current=\"step\"]{color:var(--my-action);font-weight:700}.my-config select,.my-config input{width:100%}.my-theme .my-note{font-size:.8rem}.my-error{color:var(--lb-color-error,#b42318)!important;border-inline-start:3px solid currentColor;padding-left:.7rem}.my-preview{padding:1rem;border:1px dashed var(--my-border);border-radius:var(--my-radius,.4rem)}.my-preview output{display:block;font-size:1.6rem;color:var(--my-ink);white-space:pre-wrap;overflow-wrap:anywhere}.my-summary{display:grid;grid-template-columns:minmax(6rem,1fr) minmax(0,2fr);gap:.7rem;margin:1rem