8rem}.my-step{display:grid;place-items:center;width:2.25rem;height:2.25rem;border:1px solid var(--my-action);border-radius:50%;color:var(--my-action);font-weight:600}.my-process h3{font-size:1rem;margin:0 0 .4rem}.my-process p{font-size:.875rem;margin:0}.my-heading{display:flex;justify-content:space-between;align-items:end;gap:1.5rem;margin-bottom:1.6rem}.my-heading h2{margin:0}.my-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.5rem}.my-grid[data-columns=\"3\"]{grid-template-columns:repeat(3,minmax(0,1fr))}.my-card{background:var(--my-surface);border:1px solid var(--my-border);border-radius:var(--my-radius,.8rem);overflow:hidden}.my-card-image{display:block;position:relative;background:var(--my-canvas);aspect-ratio:4/3}.my-card-image img{width:100%;height:100%;object-fit:contain}.my-card-body{padding:1.4rem}.my-card h3{margin:0}.my-card h3 a{text-decoration:none}.my-price{font-weight:600;color:var(--my-ink)!important;font-variant-numeric:tabular-nums}.my-capabilities{list-style:none;padding:0;font-size:.875rem;color:var(--my-muted)}.my-capabilities li{padding-block:.25rem}.my-unavailable{position:absolute;bottom:.75rem;left:.75rem;background:var(--my-surface);padding:.4rem .8rem;border:1px solid var(--my-border);border-radius:var(--my-radius,.4rem);font-size:.8rem}.my-empty-image{display:grid;place-items:center;height:100%;padding:2rem;text-align:center;color:var(--my-muted)}.my-collections{display:flex;flex-wrap:wrap;gap:.75rem}.my-collections a{border:1px solid var(--my-border);padding:.7rem 1.2rem;border-radius:3rem;background:var(--my-surface);min-height:2.75rem}.my-story{display:grid;grid-template-columns:1fr 1fr;gap:3rem;align-items:center}.my-story>img{width:100%;aspect-ratio:4/3;object-fit:contain;border-radius:var(--my-radius,.8rem)}.my-story-no-image{grid-template-columns:1fr;max-width:50rem}.my-filters{display:flex;flex-wrap:wrap;gap:1rem;align-items:end;margin-top:1.5rem}.my-filters label{flex:1;min-width:9rem}.my-filters input{wid