type":"text"}},"label":"Typography"}}}},"layout":{"theme":{"path":"layout/theme.liquid","source":"<!doctype html>\n<html lang=\"{{ request.locale | default: \"en\" }}\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  {% assign lb_page_title = shop.name %}\n  {% assign lb_meta_description = settings.metaDescription | default: shop.description | strip_html | truncate: 160 %}\n  <title>{{ lb_page_title }}</title>\n  {% if lb_meta_description != blank %}<meta name=\"description\" content=\"{{ lb_meta_description }}\">{% endif %}\n  <meta name=\"twitter:card\" content=\"{% if settings.socialImageUrl != blank %}summary_large_image{% else %}summary{% endif %}\">\n  <meta name=\"twitter:title\" content=\"{{ lb_page_title }}\">\n  {% if lb_meta_description != blank %}<meta name=\"twitter:description\" content=\"{{ lb_meta_description }}\">{% endif %}\n  {% if settings.socialImageUrl != blank %}<meta name=\"twitter:image\" content=\"{{ settings.socialImageUrl | image_url }}\">{% endif %}\n  <style data-lb-layout=\"1\">\n    :root{--lb-focus-ring-width:2px;--lb-focus-ring-color:var(--accent,#2563eb);--lb-focus-offset:2px;--lb-space-sm:0.5rem;--lb-space-md:0.75rem;--lb-space-lg:1rem;--lb-radius-sm:0.375rem;--lb-layout-max:72rem;--lb-layout-gutter:1rem;--lb-layout-breakpoint:48em;}\n    .lb-theme :where(a,button,input,select,textarea,summary,details,[tabindex]):focus-visible{outline:var(--lb-focus-ring-width) solid var(--lb-focus-ring-color);outline-offset:var(--lb-focus-offset);}\n    .lb-skip-link{position:absolute;left:-9999px;top:0;z-index:100;padding:var(--lb-space-md) var(--lb-space-lg);border-radius:var(--lb-radius-sm);background:var(--surface,#f8fafc);color:var(--foreground,#1a1a2e);font-weight:600;}\n    .lb-skip-link:focus,.lb-skip-link:focus-visible{left:var(--lb-space-lg);top:var(--lb-space-lg);}\n    .lb-layout__header,.lb-layout__footer{display:flex;flex-direction:column;align-items:flex-start;gap:var(--lb-space-md);margin-inline:auto;max-width:min(var(--lb-layout-max),calc(100vw - var(--lb-layout-gutter) * 2));padding-block:var(--lb-space-lg);padding-inline:var(--lb-layout-gutter);}\n    .lb-layout__brand{font-family:var(--font-display,inherit);font-weight:700;}\n    .lb-layout__nav{display:flex;flex-wrap:wrap;gap:var(--lb-space-md);}\n    .lb-layout__legal{margin:0;font-size:0.875rem;}\n    @media (min-width:48em){.lb-layout__header,.lb-layout__footer{flex-direction:row;align-items:center;justify-content:space-between;}}\n  </style>\n  {{ content_for_header | raw }}\n<style data-niche-order-presentation=\"1\">.lb-order-facts{min-width:0;max-width:100%;margin-block:.75rem}.lb-order-facts>summary{min-height:44px;cursor:pointer;padding-block:.5rem}.lb-order-facts__text{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}.lb-order-facts__missing{font-size:.875em;overflow-wrap:anywhere}</style>\n<style data-kindred=\"2\">\n.kr-theme{--kr-action:var(--primary,#662e42);--kr-canvas:var(--background,#fffaf4);--kr-text:var(--foreground,#342c2c);--kr-surface:var(--surface,#f2e7df);--kr-muted:color-mix(in srgb,var(--kr-text) 75%,var(--kr-canvas));--kr-border:color-mix(in srgb,var(--kr-text) 32%,var(--kr-canvas));color:var(--kr-text);background:var(--kr-canvas);font-family:var(--font-main,Lato,Arial,sans-serif);font-size:1rem;line-height:1.55;overflow-wrap:anywhere}\n.kr-theme *{box-sizing:border-box}.kr-theme :where(h1,h2,h3,p,figure){margin:0}.kr-theme :where(h1,h2,h3){font-family:var(--font-heading,'Playfair Display',Georgia,serif);font-weight:400;letter-spacing:-.025em;line-height:1.15}.kr-theme h1{font-size:clamp(2.1rem,4vw,3.5rem)}.kr-theme h2{font-size:clamp(1.7rem,3vw,2.4rem)}.kr-theme h3{font-size:1.5rem}.kr-theme p{color:var(--kr-muted);margin-block:.75rem}.kr-theme a{color:inherit;text-decoration:none}.kr-theme a:hover{text-decoration:underline;text-underline-offset:.2em}.kr-theme img{display:block;max-width:100%;height:auto}.kr-theme :where(button,input,select,textarea){font:inherit}.kr-theme :where(a,button,input,select,summary):focus-visible{outline:var(--lb-focus-ring-width,2px) solid var(--lb-color-focus-ring,#005fcc);outline-offset:var(--lb-focus-offset,3px)}.kr-theme :where(button){cursor:pointer}.kr-theme :where(button:disabled){cursor:default;opacity:.65}.kr-wrap{width:min(75rem,calc(100% - 6rem));margin-inline:auto}.kr-section{padding-block:3.5rem}.kr-eyebrow{font-size:.75rem;font-weight:700;letter-spacing:.12em;color:var(--kr-action)!important;text-transform:uppercase}.kr-heading{display:flex;justify-content:space-between;align-items:end;gap:2rem;margin-bottom:1.8rem}.kr-heading p{max-width:28rem}.kr-button,.kr-theme .lb-product-detail__cta--primary{display:inline-flex;align-items:center;justify-content:center;gap:1rem;min-height:3.125rem;padding:.9rem 1.4rem;border:1px solid var(--kr-action);border-radius:var(--radius,.375rem);background:var(--kr-action);color:var(--lb-color-primary-cta-text,#fff);font-weight:700;line-height:1.3;text-align:center}.kr-link{display:inline-block;color:var(--kr-action)!important;border-bottom:1px solid var(--kr-border);padding-block:.25rem;font-weight:700}.kr-intro{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);grid-template-areas:'copy image' 'finder image';gap:1.8rem 3.5rem;padding-top:3rem}.kr-intro-empty{grid-template-areas:'copy finder';padding-bottom:1rem}.kr-intro-copy{grid-area:copy}.kr-intro-copy h1{margin-top:.8rem}.kr-intro-image{grid-area:image;min-width:0;align-self:stretch}.kr-intro-image img{width:100%;height:100%;max-height:42rem;object-fit:contain;background:var(--kr-surface);border-radius:.6rem}.kr-finder-panel{grid-area:finder;background:var(--kr-surface);border:1px solid var(--kr-border);border-radius:var(--radius,.5rem);padding:1.6rem;align-self:start}.kr-finder-panel h2{font-size:1.6rem;margin-bottom:1rem}.kr-finder{display:grid;gap:1rem}.kr-theme label{display:grid;gap:.45rem;font-size:.875rem;font-weight:700;min-width:0}.kr-theme :where(input,select,textarea){width:100%;min-height:2.9rem;padding:.7rem .8rem;border:1px solid var(--kr-border);border-radius:var(--radius,.375rem);background:var(--kr-canvas);color:var(--kr-text);min-width:0}.kr-budget{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.kr-finder-panel>.kr-link{margin-top:1rem}.kr-occasions{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border-block:1px solid var(--kr-border)}.kr-occasion{padding:1.6rem 1.3rem;min-width:0;border-inline-start:1px solid var(--kr-border)}.kr-occasion:first-child{border-inline-start:0}.kr-occasion h3{font-size:1.5rem}.kr-occasion p{font-size:.875rem}.kr-grid{display:grid;grid-template-columns:repeat(var(--kr-columns,2),minmax(0,1fr));gap:2rem}.kr-columns-3{--kr-columns:3}.kr-card{min-width:0}.kr-card-media{aspect-ratio:4/3;position:relative;background:var(--kr-surface);border-radius:.6rem}.kr-card-media img{width:100%;height:100%;object-fit:contain;border-radius:inherit}.kr-placeholder{display:grid;place-items:center;min-height:10rem;padding:1.5rem;color:var(--kr-muted);text-align:center}.kr-card-meta{display:flex;justify-content:space-between;gap:1rem;margin-block:1rem .5rem;font-size:.875rem}.kr-card h3{font-size:1.65rem}.kr-card p{font-size:.9rem}.kr-card .kr-link{font-size:.85rem}.kr-unavailable{position:absolute;inset:auto .7rem .7rem;background:var(--kr-canvas);padding:.4rem .7rem;border:1px solid var(--kr-border);font-size:.8rem}.kr-pack-story{background:var(--kr-surface)}.kr-split{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:4rem}.kr-split>img{width:100%;aspect-ratio:4/3;object-fit:contain;border-radius:.6rem}.kr-split h2{margin-block:1rem}.kr-help-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:2rem}.kr-help-grid>article{padding-top:1.2rem;border-top:1px solid var(--kr-border)}.kr-help-grid p{font-size:.95rem}.kr-filter-form{display:grid;grid-template-columns:1fr 1fr 1.4fr 1fr auto;gap:1rem;align-items:end}.kr-applied-filters{display:flex;