{display:flex;flex-wrap:wrap;gap:1rem;align-items:center}.kr-theme .lb-product-detail__quantity{width:5rem}.kr-theme .lb-product-detail__accordion{padding-block:1rem;border-top:1px solid var(--kr-border);margin-top:1rem}.kr-theme .lb-product-detail__accordion summary{font-family:var(--font-heading,Georgia,serif);font-size:1.4rem;cursor:pointer}.kr-facts{border-top:1px solid var(--kr-border);padding-block:1.2rem}.kr-facts h2{font-size:1.5rem}.kr-facts ol{list-style:decimal;padding-left:1.4rem}.kr-facts li{padding:.8rem 0;border-bottom:1px solid var(--kr-border)}.kr-facts li strong{font-weight:700}.kr-facts li p{margin-block:.35rem;font-size:.875rem}.kr-media-pair{display:grid;grid-template-columns:1fr 1fr;gap:1.5rem;margin-block:2rem}.kr-media-pair img{width:100%;aspect-ratio:4/3;object-fit:contain;background:var(--kr-surface);border-radius:.5rem}.kr-media-pair figcaption{font-size:.875rem;padding-top:.65rem}.kr-theme :where(.lb-cart-summary,.lb-customer-account,.lb-customer-addresses,.lb-customer-orders,.lb-customer-order-detail,.lb-customer-settings,.lb-page-content,.lb-policy-content){max-width:min(75rem,calc(100% - 4rem));margin-inline:auto;padding-block:2rem}.kr-theme .lb-header,.kr-theme .lb-footer{background:var(--kr-canvas);color:var(--kr-text);border-color:var(--kr-border)}.kr-theme .lb-header__brand{font-family:var(--font-heading,Georgia,serif);font-size:2rem;font-weight:400}.kr-theme .lb-announcement-bar{background:var(--kr-action);color:var(--lb-color-primary-cta-text,#fff)}\n@media(max-width:70rem){.kr-wrap{width:calc(100% - 4rem)}.kr-intro{gap:1.5rem}.kr-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.kr-filter-form{grid-template-columns:1fr 1fr}.kr-filter-form>.kr-budget{grid-column:1/-1}.kr-help-grid{gap:1.3rem}.kr-theme .lb-product-detail__layout{gap:2rem}.kr-occasions{grid-template-columns:1fr 1fr}.kr-occasion:nth-child(3){border-inline-start:0;border-top:1px solid var(--kr-border)}.kr-occasion:nth-child(4){border-top:1px solid var(--kr-border)}