a href=\"{{ link.url | store_url }}\">{{ link.title }}</a>{% endfor %}</nav>{% endif %}\n    <p class=\"lb-layout__legal\">&copy; {{ shop.name }}</p>\n  </footer>\n  {{ content_for_footer | raw }}\n</body>\n</html>"}},"manifest_version":"2026-06-liquid-sections","schema_manifest":{"blocks_path":"blocks/*.liquid","bundle_schema_version":"2026-06-liquid-sections","engine":"liquid","layout_path":"layout/theme.liquid","locales_path":"locales/*.json","sections_path":"sections/*.liquid","settings_data_path":"config/settings_data.json","settings_path":"config/settings_schema.json","templates_path":"templates/*.json"},"section_schemas":{"404-page":{"blocks_schema":{},"defaults":{},"description":"Liquid section file sections/404-page.liquid","name":"404 Not Found","presets":[{"name":"404 Not Found","settings":{}}],"renderer_key":"liquid.section.404-page","settings_schema":{},"source_path":"sections/404-page.liquid","type":"404-page"},"about-section":{"blocks_schema":{},"defaults":{},"description":"Liquid section file sections/about-section.liquid","name":"Packaging and contents editorial","presets":[{"name":"Packaging and contents editorial","settings":{}}],"renderer_key":"liquid.section.about-section","settings_schema":{"content":{"default":"","label":"Merchant explanation","type":"text"},"eyebrow":{"default":"WHAT THEY OPEN MATTERS","label":"Eyebrow","type":"text"},"image":{"label":"Packaging photograph","type":"image"},"imageAlt":{"default":"","label":"Image description","type":"text"},"linkLabel":{"default":"","label":"Link label","type":"text"},"linkUrl":{"default":"","label":"Link destination","type":"url"},"title":{"default":"No guesswork in the unboxing.","label":"Heading","type":"text"}},"source_path":"sections/about-section.liquid","type":"about-section"},"announcement-bar":{"blocks_schema":{},"defaults":{},"description":"Liquid section file sections/announcement-bar.liquid","name":"Announcement Bar","presets":[{"name":"Announcement Bar","settings":{}}],"renderer_k