 OR t.config IS DISTINCT FROM (prior->'config'||jsonb_build_object('firstPartyOrderHeading211',jsonb_build_object('payloadSha256','da476dc47ce16d55cd3a7ee05170e9618860febd844c7fcb83aaf349d00806b9','previous',prior)))
